func Contains(a, b any) bool {
	if Compare(a, b) == 0 {
		return true
	}
	ta, tb := TypeName(a), TypeName(b)
	if ta == "string" && tb == "string" {
		return strings.Contains(a.(string), b.(string))
	}
	if ta == "array" && tb == "array" {
		aa, ab := a.([]any), b.([]any)
		for _, elemB := range ab {
			found := false
			for _, elemA := range aa {
				if Contains(elemA, elemB) {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	}
	if ta == "object" && tb == "object" {
		entriesB := GetSortedEntries(b)
		for _, eb := range entriesB {
			valA, exists := getObjectKey(a, eb.Key)
			if !exists || !Contains(valA, eb.Val) {
				return false
			}
		}
		return true
	}
	return false
}

func getObjectKey(obj any, key string) (any, bool) {
	if o, ok := obj.(*JqObject); ok {
		val, exists := o.Map[key]
		return val, exists
	}
	if m, ok := obj.(map[string]any); ok {
		val, exists := m[key]
		return val, exists
	}
	return nil, false
}

func parseNumberString(s string) (float64, error) {
	var f float64
	_, err := fmt.Sscanf(s, "%f", &f)
	return f, err
}

func compileRegex(patStr string, flagsStr string) (*regexp.Regexp, bool, error) {
	global := false
	prefix := ""
	for _, ch := range flagsStr {
		switch ch {
		case 'i':
			prefix += "(?i)"
		case 'm':
			prefix += "(?m)"
		case 's':
			prefix += "(?s)"
		case 'x':
			prefix += "(?x)"
		case 'g':
			global = true
		}
	}
	re, err := regexp.Compile(prefix + patStr)
	return re, global, err
}

func runRegexTest(ctx *Context, input any, patAST, flagsAST ASTNode, emit func(any) error) error {
	s, ok := input.(string)
	if !ok {
		return fmt.Errorf("test requires string input")
	}
	return Eval(patAST, ctx, input, func(pVal any) error {
		pStr, ok := pVal.(string)
		if !ok {
			return fmt.Errorf("test pattern must be string")
		}
		flagsStr := ""
		if flagsAST != nil {
			Eval(flagsAST, ctx, input, func(fVal any) error {
				if fs, ok := fVal.(string); ok {
					flagsStr = fs
				}
				return nil
			})
		}
		re, _, err := compileRegex(pStr, flagsStr)
		if err != nil {
			return err
		}
		return emit(re.MatchString(s))
	})
}

func runRegexMatch(ctx *Context, input any, patAST, flagsAST ASTNode, emit func(any) error) error {
	s, ok := input.(string)
	if !ok {
		return fmt.Errorf("match requires string input")
	}
	return Eval(patAST, ctx, input, func(pVal any) error {
		pStr, ok := pVal.(string)
		if !ok {
			return fmt.Errorf("match pattern must be string")
		}
		flagsStr := ""
		if flagsAST != nil {
			Eval(flagsAST, ctx, input, func(fVal any) error {
				if fs, ok := fVal.(string); ok {
					flagsStr = fs
				}
				return nil
			})
		}
		re, global, err := compileRegex(pStr, flagsStr)
		if err != nil {
			return err
		}

		names := re.SubexpNames()
		matches := re.FindAllStringSubmatchIndex(s, -1)
		if matches == nil {
			return nil
		}

		for _, m := range matches {
			if !global && m[0] == -1 {
				continue
			}
			obj := NewJqObject()
			obj.Set("offset", m[0])
			obj.Set("length", m[1]-m[0])
			obj.Set("string", s[m[0]:m[1]])
			var captures []any
			for i := 1; i < len(m)/2; i++ {
				capObj := NewJqObject()
				if m[2*i] >= 0 {
					capObj.Set("offset", m[2*i])
					capObj.Set("length", m[2*i+1]-m[2*i])
					capObj.Set("string", s[m[2*i]:m[2*i+1]])
				} else {
					capObj.Set("offset", -1)
					capObj.Set("length", 0)
					capObj.Set("string", nil)
				}
				if names[i] != "" {
					capObj.Set("name", names[i])
				} else {
					capObj.Set("name", nil)
				}
				captures = append(captures, capObj)
			}
			obj.Set("captures", captures)
			if err := emit(obj); err != nil {
				return err
			}
			if !global {
				break
			}
		}
		return nil
	})
}

func runRegexCapture(ctx *Context, input any, patAST, flagsAST ASTNode, emit func(any) error) error {
	s, ok := input.(string)
	if !ok {
		return fmt.Errorf("capture requires string input")
	}
	return Eval(patAST, ctx, input, func(pVal any) error {
		pStr, ok := pVal.(string)
		if !ok {
			return fmt.Errorf("capture pattern must be string")
		}
		flagsStr := ""
		if flagsAST != nil {
			Eval(flagsAST, ctx, input, func(fVal any) error {
				if fs, ok := fVal.(string); ok {
					flagsStr = fs
				}
				return nil
			})
		}
		re, global, err := compileRegex(pStr, flagsStr)
		if err != nil {
			return err
		}

		names := re.SubexpNames()
		matches := re.FindAllStringSubmatchIndex(s, -1)
		for _, m := range matches {
			obj := NewJqObject()
			for i := 1; i < len(names); i++ {
				if names[i] != "" {
					if m[2*i] >= 0 {
						obj.Set(names[i], s[m[2*i]:m[2*i+1]])
					} else {
						obj.Set(names[i], nil)
					}
				}
			}
			if err := emit(obj); err != nil {
				return err
			}
			if !global {
				break
			}
		}
		return nil
	})
}

func runRegexSub(ctx *Context, input any, patAST, replAST, flagsAST ASTNode, global bool, emit func(any) error) error {
	s, ok := input.(string)
	if !ok {
		return fmt.Errorf("sub/gsub requires string input")
	}
	return Eval(patAST, ctx, input, func(pVal any) error {
		pStr, ok := pVal.(string)
		if !ok {
			return fmt.Errorf("sub pattern must be string")
		}
		flagsStr := ""
		if flagsAST != nil {
			Eval(flagsAST, ctx, input, func(fVal any) error {
				if fs, ok := fVal.(string); ok {
					flagsStr = fs
				}
				return nil
			})
		}
		re, isGlobal, err := compileRegex(pStr, flagsStr)
		if err != nil {
			return err
		}
		if global {
			isGlobal = true
		}

		return Eval(replAST, ctx, input, func(rVal any) error {
			rStr, ok := rVal.(string)
			if !ok {
				return fmt.Errorf("replacement must be string")
			}
			if isGlobal {
				return emit(re.ReplaceAllString(s, rStr))
			}
			loc := re.FindStringIndex(s)
			if loc == nil {
				return emit(s)
			}
			res := s[:loc[0]] + re.ReplaceAllString(s[loc[0]:loc[1]], rStr) + s[loc[1]:]
			return emit(res)
		})
	})
}

func runRegexScan(ctx *Context, input any, patAST, flagsAST ASTNode, emit func(any) error) error {
	s, ok := input.(string)
	if !ok {
		return fmt.Errorf("scan requires string input")
	}
	return Eval(patAST, ctx, input, func(pVal any) error {
		pStr, ok := pVal.(string)
		if !ok {
			return fmt.Errorf("scan pattern must be string")
		}
		flagsStr := "g"
		if flagsAST != nil {
			Eval(flagsAST, ctx, input, func(fVal any) error {
				if fs, ok := fVal.(string); ok {
					flagsStr = fs
				}
				return nil
			})
		}
		re, _, err := compileRegex(pStr, flagsStr)
		if err != nil {
			return err
		}

		numGroups := re.NumSubexp()
		if numGroups == 0 {
			matches := re.FindAllString(s, -1)
			for _, m := range matches {
				if err := emit(m); err != nil {
					return err
				}
			}
		} else {
			matches := re.FindAllStringSubmatch(s, -1)
			for _, m := range matches {
				res := make([]any, len(m)-1)
				for i := 1; i < len(m); i++ {
					res[i-1] = m[i]
				}
				if err := emit(res); err != nil {
					return err
				}
			}
		}
		return nil
	})
}
EOF"}

