func Contains(a, b any) bool {
	if Compare(a, b) == 0 {
		return true
	}
	ta, tb := TypeName(a), TypeName(b)
	if ta == "string" && tb == "string" {
		return strings.Contains(a.(string), b.(string))
	}
	if ta == "array" && tb == "array" {
		aa, ab := a.([]any), b.([]any)
		for _, elemB := range ab {
			found := false
			for _, elemA := range aa {
				if Contains(elemA, elemB) {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	}
	if ta == "object" && tb == "object" {
		entriesB := GetSortedEntries(b)
		for _, eb := range entriesB {
			valA, exists := getObjectKey(a, eb.Key)
			if !exists || !Contains(valA, eb.Val) {
				return false
			}
		}
		return true
	}
	return false
}

func getObjectKey(obj any, key string) (any, bool) {
	if o, ok := obj.(*JqObject); ok {
		val, exists := o.Map[key]
		return val, exists
	}
	if m, ok := obj.(map[string]any); ok {
		val, exists := m[key]
		return val, exists
	}
	return nil, false
}

func parseNumberString(s string) (float64, error) {
	var f float64
	_, err := fmt.Sscanf(s, "%f", &f)
	return f, err
}

func compileRegex(patStr string, flagsStr string) (*regexp.Regexp, bool, error) {
	global := false
	prefix := ""
	for _, ch := range flagsStr {
		switch ch {
		case 'i':
			prefix += "(?i)"
		case 'm':
			prefix += "(?m)"
		case 's':
			prefix += "(?s)"
		case 'x':
			prefix += "(?x)"
		case 'g':
			global = true
		}
	}
	re, err := regexp.Compile(prefix + patStr)
	return re, global, err
}

func runRegexTest(ctx *Context, input any, patAST, flagsAST ASTNode, emit func(any) error) error {
	s, ok := input.(string)
	if !ok {
		return fmt.Errorf("test requires string input")
	}
	return Eval(patAST, ctx, input, func(pVal any) error {
		pStr, ok := pVal.(string)
		if !ok {
			return fmt.Errorf("test pattern must be string")
		}
		flagsStr := ""
		if flagsAST != nil {
			Eval(flagsAST, ctx, input, func(fVal any) error {
				if fs, ok := fVal.(string); ok {
					flagsStr = fs
				}
				return nil
			})
		}
		re, _, err := compileRegex(pStr, flagsStr)
		if err != nil {
			return err
		}
		return emit(re.MatchString(s))
