			i++
			break
		}
		if arg == "-V" || arg == "--version" {
			fmt.Println("jq-build-f77602d")
			os.Exit(0)
		}
		if arg == "--build-configuration" {
			fmt.Println("--disable-docs --with-oniguruma=builtin --enable-static --enable-all-static --prefix=/usr/local")
