		}
		if arg == "-h" || arg == "--help" {
			fmt.Print(HelpText)
			os.Exit(0)
		}

		if arg == "--args" {
			i++
			if filterStr == "" && filterFile == "" && i < len(args) {
				filterStr = args[i]
				i++
			}
			for i < len(args) {
				positionalArgs = append(positionalArgs, args[i])
				i++
			}
