	case []any:
		if len(val) == 0 {
			if opts.Color {
				buf.WriteString(colorBold)
			}
			buf.WriteString("[]")
			if opts.Color {
				buf.WriteString(colorReset)
			}
			return
		}
		if opts.Compact {
