			if opts.Color {
				buf.WriteString(colorBold)
			}
			buf.WriteString("]")
			if opts.Color {
				buf.WriteString(colorReset)
			}
		} else {
			if opts.Color {
				buf.WriteString(colorBold)
			}
			buf.WriteString("[\n")
			if opts.Color {
				buf.WriteString(colorReset)
			}
			for i, elem := range val {
				if i > 0 {
					if opts.Color {
						buf.WriteString(colorBold)
					}
					buf.WriteString(",\n")
					if opts.Color {
						buf.WriteString(colorReset)
					}
				}
				writeIndent(level + 1)
				formatRecursive(elem, buf, opts, level+1)
			}
			buf.WriteString("\n")
			writeIndent(level)
			if opts.Color {
				buf.WriteString(colorBold)
			}
			buf.WriteString("]")
			if opts.Color {
				buf.WriteString(colorReset)
			}
