type JqObject struct {
	Keys []string
	Map  map[string]any
}

func NewJqObject() *JqObject {
	return &JqObject{
		Keys: make([]string, 0),
		Map:  make(map[string]any),
	}
}

func (o *JqObject) Set(k string, v any) {
	if _, exists := o.Map[k]; !exists {
		o.Keys = append(o.Keys, k)
	}
	o.Map[k] = v
}

func (o *JqObject) Delete(k string) {
	if _, exists := o.Map[k]; exists {
		delete(o.Map, k)
		newKeys := make([]string, 0, len(o.Keys))
		for _, key := range o.Keys {
			if key != k {
				newKeys = append(newKeys, key)
			}
		}
		o.Keys = newKeys
	}
}

func (o *JqObject) Clone() *JqObject {
	no := NewJqObject()
	for _, k := range o.Keys {
		no.Set(k, DeepCopy(o.Map[k]))
	}
	return no
}

func DeepCopy(v any) any {
	if v == nil {
		return nil
	}
	switch val := v.(type) {
	case bool, float64, int, int64, json.Number, string:
		return val
	case []any:
		res := make([]any, len(val))
		for i, elem := range val {
			res[i] = DeepCopy(elem)
		}
		return res
	case *JqObject:
		return val.Clone()
	case map[string]any:
		no := NewJqObject()
		for k, elem := range val {
			no.Set(k, DeepCopy(elem))
		}
		return no
	}
	return v
}

func TypeOrder(val any) int {
	if val == nil {
		return 0
	}
	switch val.(type) {
	case bool:
		return 1
	case float64, int, int64, json.Number:
		return 2
	case string:
		return 3
	case []any:
		return 4
	case *JqObject, map[string]any:
		return 5
	}
	return 6
}

func ToFloat(v any) float64 {
	switch val := v.(type) {
	case float64:
		return val
	case int:
		return float64(val)
	case int64:
		return float64(val)
	case json.Number:
		f, _ := val.Float64()
		return f
	case bool:
		if val {
			return 1
		}
		return 0
	}
	return 0
}

type Entry struct {
	Key string
	Val any
}

func GetSortedEntries(v any) []Entry {
	var entries []Entry
	switch obj := v.(type) {
	case *JqObject:
		for _, k := range obj.Keys {
			entries = append(entries, Entry{Key: k, Val: obj.Map[k]})
		}
	case map[string]any:
		for k, val := range obj {
			entries = append(entries, Entry{Key: k, Val: val})
		}
	}
	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Key < entries[j].Key
	})
	return entries
}

func Compare(a, b any) int {
	ta, tb := TypeOrder(a), TypeOrder(b)
	if ta != tb {
		if ta < tb {
			return -1
		}
		return 1
	}
	switch ta {
	case 0:
		return 0
	case 1:
		ba, bb := a.(bool), b.(bool)
		if ba == bb {
			return 0
		}
		if !ba && bb {
			return -1
		}
		return 1
	case 2:
		fa, fb := ToFloat(a), ToFloat(b)
		if fa < fb {
			return -1
		}
		if fa > fb {
			return 1
		}
		return 0
	case 3:
		sa, sb := a.(string), b.(string)
		if sa < sb {
			return -1
		}
		if sa > sb {
			return 1
		}
		return 0
	case 4:
		aa, ab := a.([]any), b.([]any)
		minLen := len(aa)
		if len(ab) < minLen {
			minLen = len(ab)
		}
		for i := 0; i < minLen; i++ {
			cmp := Compare(aa[i], ab[i])
			if cmp != 0 {
				return cmp
			}
		}
		if len(aa) < len(ab) {
			return -1
		}
		if len(aa) > len(ab) {
			return 1
		}
		return 0
	case 5:
		oa, ob := GetSortedEntries(a), GetSortedEntries(b)
		minLen := len(oa)
		if len(ob) < minLen {
			minLen = len(ob)
		}
		for i := 0; i < minLen; i++ {
			if oa[i].Key < ob[i].Key {
				return -1
			}
			if oa[i].Key > ob[i].Key {
				return 1
			}
			cmp := Compare(oa[i].Val, ob[i].Val)
			if cmp != 0 {
				return cmp
			}
		}
		if len(oa) < len(ob) {
			return -1
		}
		if len(oa) > len(ob) {
			return 1
		}
		return 0
	}
	return 0
}

func IsTruthy(v any) bool {
	if v == nil {
		return false
	}
	if b, ok := v.(bool); ok {
		return b
	}
	return true
}

func TypeName(v any) string {
	if v == nil {
		return "null"
	}
	switch v.(type) {
	case bool:
		return "boolean"
	case float64, int, int64, json.Number:
		return "number"
	case string:
		return "string"
	case []any:
		return "array"
	case *JqObject, map[string]any:
		return "object"
	}
	return "unknown"
}

func Add(a, b any) (any, error) {
	if a == nil {
		return b, nil
	}
	if b == nil {
		return a, nil
	}
	ta, tb := TypeName(a), TypeName(b)
	if ta == "number" && tb == "number" {
		return ToFloat(a) + ToFloat(b), nil
	}
	if ta == "string" && tb == "string" {
		return a.(string) + b.(string), nil
	}
	if ta == "array" && tb == "array" {
		aa, ab := a.([]any), b.([]any)
		res := make([]any, 0, len(aa)+len(ab))
		res = append(res, aa...)
		res = append(res, ab...)
		return res, nil
	}
	if ta == "object" && tb == "object" {
		res := NewJqObject()
		if oa, ok := a.(*JqObject); ok {
			for _, k := range oa.Keys {
				res.Set(k, DeepCopy(oa.Map[k]))
			}
		}
		if ob, ok := b.(*JqObject); ok {
			for _, k := range ob.Keys {
				res.Set(k, DeepCopy(ob.Map[k]))
			}
		}
		return res, nil
	}
	return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be added", ta, FormatCompact(a), tb, FormatCompact(b))
}

func Sub(a, b any) (any, error) {
	ta, tb := TypeName(a), TypeName(b)
	if ta == "number" && tb == "number" {
		return ToFloat(a) - ToFloat(b), nil
	}
	if ta == "array" && tb == "array" {
		aa, ab := a.([]any), b.([]any)
		res := make([]any, 0)
		for _, item := range aa {
			found := false
			for _, r := range ab {
				if Compare(item, r) == 0 {
					found = true
					break
				}
			}
			if !found {
				res = append(res, item)
			}
		}
		return res, nil
	}
	return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be subtracted", ta, FormatCompact(a), tb, FormatCompact(b))
}

func Mul(a, b any) (any, error) {
	ta, tb := TypeName(a), TypeName(b)
	if ta == "number" && tb == "number" {
		return ToFloat(a) * ToFloat(b), nil
	}
	if ta == "string" && tb == "number" {
		n := int(ToFloat(b))
		if n < 0 {
			return nil, nil
		}
		return strings.Repeat(a.(string), n), nil
	}
	if ta == "number" && tb == "string" {
		n := int(ToFloat(a))
		if n < 0 {
			return nil, nil
		}
		return strings.Repeat(b.(string), n), nil
	}
	if ta == "object" && tb == "object" {
		return MergeObjects(a, b)
	}
	return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be multiplied", ta, FormatCompact(a), tb, FormatCompact(b))
}

func MergeObjects(a, b any) (any, error) {
	res := NewJqObject()
	oa, _ := a.(*JqObject)
	ob, _ := b.(*JqObject)

	if oa != nil {
		for _, k := range oa.Keys {
			res.Set(k, DeepCopy(oa.Map[k]))
		}
	}
	if ob != nil {
		for _, k := range ob.Keys {
			if existingVal, exists := res.Map[k]; exists {
				if TypeName(existingVal) == "object" && TypeName(ob.Map[k]) == "object" {
					merged, err := MergeObjects(existingVal, ob.Map[k])
					if err != nil {
						return nil, err
					}
					res.Set(k, merged)
				} else {
					res.Set(k, DeepCopy(ob.Map[k]))
				}
			} else {
				res.Set(k, DeepCopy(ob.Map[k]))
			}
		}
	}
	return res, nil
}

func Div(a, b any) (any, error) {
	ta, tb := TypeName(a), TypeName(b)
	if ta == "number" && tb == "number" {
		fb := ToFloat(b)
		if fb == 0 {
			return nil, fmt.Errorf("number (%s) and number (0) cannot be divided because the divisor is zero", FormatCompact(a))
		}
		return ToFloat(a) / fb, nil
	}
	if ta == "string" && tb == "string" {
		s := a.(string)
		delim := b.(string)
		if delim == "" {
			runes := []rune(s)
			res := make([]any, len(runes))
			for i, r := range runes {
				res[i] = string(r)
			}
			return res, nil
		}
		parts := strings.Split(s, delim)
		res := make([]any, len(parts))
		for i, p := range parts {
			res[i] = p
		}
		return res, nil
	}
	return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be divided", ta, FormatCompact(a), tb, FormatCompact(b))
}

func Mod(a, b any) (any, error) {
	ta, tb := TypeName(a), TypeName(b)
	if ta == "number" && tb == "number" {
		ia := int64(ToFloat(a))
		ib := int64(ToFloat(b))
		if ib == 0 {
			return nil, fmt.Errorf("number (%s) and number (0) cannot be divided because the divisor is zero", FormatCompact(a))
		}
		return float64(ia % ib), nil
	}
	return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be divided (remainder)", ta, FormatCompact(a), tb, FormatCompact(b))
}

func FormatCompact(v any) string {
	opts := FormatOptions{Compact: true}
	return FormatValue(v, opts)
}

type FormatOptions struct {
	Compact  bool
	Raw      bool
	Indent   int // spaces, or -1 for tab
	SortKeys bool
	ASCII    bool
	Color    bool
	Join     bool
	NullTerm bool
	Seq      bool
}

func FormatValue(v any, opts FormatOptions) string {
	var buf bytes.Buffer
	formatRecursive(v, &buf, opts, 0)
	return buf.String()
}

func formatRecursive(v any, buf *bytes.Buffer, opts FormatOptions, level int) {
	indentStr := "  "
	if opts.Indent > 0 {
		indentStr = strings.Repeat(" ", opts.Indent)
	} else if opts.Indent == -1 {
		indentStr = "\t"
	}

	writeIndent := func(lvl int) {
		for i := 0; i < lvl; i++ {
			buf.WriteString(indentStr)
		}
	}

	colorReset := "\x1b[0m"
	colorBold := "\x1b[1;39m"
	colorKey := "\x1b[1;34m"
	colorString := "\x1b[0;32m"
	colorNumber := "\x1b[0;39m"
	colorNull := "\x1b[0;90m"

	if v == nil {
		if opts.Color {
			buf.WriteString(colorNull)
		}
		buf.WriteString("null")
		if opts.Color {
			buf.WriteString(colorReset)
		}
		return
	}

	switch val := v.(type) {
	case bool:
		if opts.Color {
			buf.WriteString(colorNumber)
		}
		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
		if opts.Color {
			buf.WriteString(colorReset)
		}
	case float64:
		if opts.Color {
			buf.WriteString(colorNumber)
		}
		if math.IsNaN(val) || math.IsInf(val, 0) {
			buf.WriteString("null")
		} else {
			s := strconv.FormatFloat(val, 'f', -1, 64)
			buf.WriteString(s)
		}
		if opts.Color {
			buf.WriteString(colorReset)
		}
	case int:
		if opts.Color {
			buf.WriteString(colorNumber)
		}
		buf.WriteString(strconv.Itoa(val))
		if opts.Color {
			buf.WriteString(colorReset)
		}
	case int64:
		if opts.Color {
			buf.WriteString(colorNumber)
		}
		buf.WriteString(strconv.FormatInt(val, 10))
		if opts.Color {
			buf.WriteString(colorReset)
		}
	case json.Number:
		if opts.Color {
			buf.WriteString(colorNumber)
		}
		buf.WriteString(val.String())
		if opts.Color {
			buf.WriteString(colorReset)
		}
	case string:
		if opts.Color {
			buf.WriteString(colorString)
		}
		formatString(val, buf, opts.ASCII)
		if opts.Color {
			buf.WriteString(colorReset)
		}
	case []any:
		if len(val) == 0 {
			if opts.Color {
				buf.WriteString(colorBold)
			}
			buf.WriteString("[]")
			if opts.Color {
				buf.WriteString(colorReset)
			}
			return
		}
		if opts.Compact {
			if opts.Color {
				buf.WriteString(colorBold)
			}
			buf.WriteString("[")
			if opts.Color {
				buf.WriteString(colorReset)
			}
			for i, elem := range val {
				if i > 0 {
					if opts.Color {
						buf.WriteString(colorBold)
					}
					buf.WriteString(",")
					if opts.Color {
						buf.WriteString(colorReset)
					}
				}
				formatRecursive(elem, buf, opts, level)
			}
			if opts.Color {
				buf.WriteString(colorBold)
			}
			buf.WriteString("]")
			if opts.Color {
				buf.WriteString(colorReset)
			}
		} else {
			if opts.Color {
				buf.WriteString(colorBold)
			}
			buf.WriteString("[\n")
			if opts.Color {
				buf.WriteString(colorReset)
			}
			for i, elem := range val {
				if i > 0 {
					if opts.Color {
						buf.WriteString(colorBold)
					}
					buf.WriteString(",\n")
					if opts.Color {
						buf.WriteString(colorReset)
					}
				}
				writeIndent(level + 1)
				formatRecursive(elem, buf, opts, level+1)
			}
			buf.WriteString("\n")
			writeIndent(level)
			if opts.Color {
				buf.WriteString(colorBold)
			}
			buf.WriteString("]")
			if opts.Color {
				buf.WriteString(colorReset)
			}
		}
	case *JqObject:
		formatObject(val.Keys, val.Map, buf, opts, level)
	case map[string]any:
		keys := make([]string, 0, len(val))
		for k := range val {
			keys = append(keys, k)
		}
		formatObject(keys, val, buf, opts, level)
	}
}

func formatObject(keys []string, m map[string]any, buf *bytes.Buffer, opts FormatOptions, level int) {
	indentStr := "  "
	if opts.Indent > 0 {
		indentStr = strings.Repeat(" ", opts.Indent)
	} else if opts.Indent == -1 {
		indentStr = "\t"
	}

	writeIndent := func(lvl int) {
		for i := 0; i < lvl; i++ {
			buf.WriteString(indentStr)
		}
	}

	colorReset := "\x1b[0m"
	colorBold := "\x1b[1;39m"
	colorKey := "\x1b[1;34m"

	if opts.SortKeys {
		sortedKeys := make([]string, len(keys))
		copy(sortedKeys, keys)
		sort.Strings(sortedKeys)
		keys = sortedKeys
	}

	if len(keys) == 0 {
		if opts.Color {
			buf.WriteString(colorBold)
		}
		buf.WriteString("{}")
		if opts.Color {
			buf.WriteString(colorReset)
		}
		return
	}

	if opts.Compact {
		if opts.Color {
			buf.WriteString(colorBold)
		}
		buf.WriteString("{")
		if opts.Color {
			buf.WriteString(colorReset)
		}
		for i, k := range keys {
			if i > 0 {
				if opts.Color {
					buf.WriteString(colorBold)
				}
				buf.WriteString(",")
				if opts.Color {
					buf.WriteString(colorReset)
				}
			}
			if opts.Color {
				buf.WriteString(colorKey)
			}
			formatString(k, buf, opts.ASCII)
			if opts.Color {
				buf.WriteString(colorReset)
				buf.WriteString(colorBold)
			}
			buf.WriteString(":")
			if opts.Color {
				buf.WriteString(colorReset)
			}
			formatRecursive(m[k], buf, opts, level)
		}
		if opts.Color {
			buf.WriteString(colorBold)
		}
		buf.WriteString("}")
		if opts.Color {
			buf.WriteString(colorReset)
		}
	} else {
		if opts.Color {
			buf.WriteString(colorBold)
		}
		buf.WriteString("{\n")
		if opts.Color {
			buf.WriteString(colorReset)
		}
		for i, k := range keys {
			if i > 0 {
				if opts.Color {
					buf.WriteString(colorBold)
				}
				buf.WriteString(",\n")
				if opts.Color {
					buf.WriteString(colorReset)
				}
			}
			writeIndent(level + 1)
			if opts.Color {
				buf.WriteString(colorKey)
			}
			formatString(k, buf, opts.ASCII)
			if opts.Color {
				buf.WriteString(colorReset)
				buf.WriteString(colorBold)
			}
			buf.WriteString(": ")
			if opts.Color {
				buf.WriteString(colorReset)
			}
			formatRecursive(m[k], buf, opts, level+1)
		}
		buf.WriteString("\n")
		writeIndent(level)
		if opts.Color {
			buf.WriteString(colorBold)
		}
		buf.WriteString("}")
		if opts.Color {
			buf.WriteString(colorReset)
		}
	}
}

func formatString(s string, buf *bytes.Buffer, asciiOnly bool) {
	buf.WriteByte('"')
	for i := 0; i < len(s); {
		r, width := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && width == 1 {
			buf.WriteString(fmt.Sprintf("\\u00%02x", s[i]))
			i++
			continue
		}
		switch r {
		case '"':
			buf.WriteString("\\\"")
		case '\\':
			buf.WriteString("\\\\")
		case '\b':
			buf.WriteString("\\b")
		case '\f':
			buf.WriteString("\\f")
		case '\n':
			buf.WriteString("\\n")
		case '\r':
			buf.WriteString("\\r")
		case '\t':
			buf.WriteString("\\t")
		default:
			if r < 0x20 {
				buf.WriteString(fmt.Sprintf("\\u%04x", r))
			} else if asciiOnly && r >= 0x80 {
				if r <= 0xffff {
					buf.WriteString(fmt.Sprintf("\\u%04x", r))
				} else {
					r1 := 0xd800 + ((r - 0x10000) >> 10)
					r2 := 0xdc00 + ((r - 0x10000) & 0x3ff)
					buf.WriteString(fmt.Sprintf("\\u%04x\\u%04x", r1, r2))
				}
			} else {
				buf.WriteRune(r)
			}
		}
		i += width
	}
	buf.WriteByte('"')
}

func FormatCSV(v any) (string, error) {
	arr, ok := v.([]any)
	if !ok {
		return "", fmt.Errorf("cannot format %s as CSV", TypeName(v))
	}
	var parts []string
	for _, item := range arr {
		if item == nil {
			parts = append(parts, "")
		} else if s, isStr := item.(string); isStr {
			escaped := strings.ReplaceAll(s, "\"", "\"\"")
			parts = append(parts, "\""+escaped+"\"")
		} else {
			parts = append(parts, FormatCompact(item))
		}
	}
	return strings.Join(parts, ","), nil
}

func FormatTSV(v any) (string, error) {
	arr, ok := v.([]any)
	if !ok {
		return "", fmt.Errorf("cannot format %s as TSV", TypeName(v))
	}
	var parts []string
	for _, item := range arr {
		if item == nil {
			parts = append(parts, "")
		} else if s, isStr := item.(string); isStr {
			s = strings.ReplaceAll(s, "\t", "\\t")
			s = strings.ReplaceAll(s, "\n", "\\n")
			s = strings.ReplaceAll(s, "\r", "\\r")
			s = strings.ReplaceAll(s, "\\", "\\\\")
			parts = append(parts, s)
		} else {
			parts = append(parts, FormatCompact(item))
		}
	}
	return strings.Join(parts, "\t"), nil
}

func FormatSH(v any) (string, error) {
	formatSingle := func(item any) string {
		if item == nil {
			return "null"
		}
		if s, isStr := item.(string); isStr {
			escaped := strings.ReplaceAll(s, "'", "'\\''")
			return "'" + escaped + "'"
		}
		return FormatCompact(item)
	}

	if arr, ok := v.([]any); ok {
		var parts []string
		for _, item := range arr {
			parts = append(parts, formatSingle(item))
		}
		return strings.Join(parts, " "), nil
	}
	return formatSingle(v), nil
}

func FormatHTML(v any) (string, error) {
	if s, isStr := v.(string); isStr {
		return html.EscapeString(s), nil
	}
	return html.EscapeString(FormatCompact(v)), nil
}

func FormatURI(v any) (string, error) {
	if s, isStr := v.(string); isStr {
		return url.QueryEscape(s), nil
	}
	return url.QueryEscape(FormatCompact(v)), nil
}

func FormatBase64(v any) (string, error) {
	var data []byte
	if s, isStr := v.(string); isStr {
		data = []byte(s)
	} else {
		data = []byte(FormatCompact(v))
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

func FormatBase64Decode(v any) (string, error) {
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("base64decode requires string")
	}
	data, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		return "", err
	}
	return string(data), nil
}
