func decodeJSON(dec *json.Decoder) (any, error) {
	t, err := dec.Token()
	if err != nil {
		return nil, err
	}
	return parseToken(dec, t)
}

func parseToken(dec *json.Decoder, t json.Token) (any, error) {
	switch v := t.(type) {
	case nil:
		return nil, nil
	case bool:
		return v, nil
	case json.Number:
		if f, err := v.Float64(); err == nil {
			return f, nil
		}
		return v, nil
	case float64:
		return v, nil
	case string:
		return v, nil
	case json.Delim:
		if v == '[' {
			var arr []any
			for dec.More() {
				elem, err := decodeJSON(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, elem)
			}
			dec.Token() // consume ']'
			return arr, nil
		} else if v == '{' {
			obj := NewJqObject()
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				keyStr, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				val, err := decodeJSON(dec)
				if err != nil {
					return nil, err
				}
				obj.Set(keyStr, val)
			}
			dec.Token() // consume '}'
			return obj, nil
		}
	}
	return nil, fmt.Errorf("unexpected token %v", t)
}
