func DeepCopy(v any) any {
	if v == nil {
		return nil
	}
	switch val := v.(type) {
	case bool, float64, int, int64, json.Number, string:
		return val
	case []any:
		res := make([]any, len(val))
		for i, elem := range val {
			res[i] = DeepCopy(elem)
		}
		return res
	case *JqObject:
		return val.Clone()
	case map[string]any:
		no := NewJqObject()
		for k, elem := range val {
			no.Set(k, DeepCopy(elem))
		}
		return no
	}
	return v
}

func TypeOrder(val any) int {
	if val == nil {
		return 0
	}
	switch val.(type) {
	case bool:
		return 1
	case float64, int, int64, json.Number:
		return 2
	case string:
		return 3
	case []any:
		return 4
	case *JqObject, map[string]any:
		return 5
	}
	return 6
}

func ToFloat(v any) float64 {
	switch val := v.(type) {
	case float64:
		return val
	case int:
		return float64(val)
	case int64:
		return float64(val)
	case json.Number:
		f, _ := val.Float64()
		return f
	case bool:
		if val {
			return 1
		}
		return 0
	}
	return 0
}

type Entry struct {
	Key string
	Val any
}

func GetSortedEntries(v any) []Entry {
	var entries []Entry
	switch obj := v.(type) {
	case *JqObject:
		for _, k := range obj.Keys {
			entries = append(entries, Entry{Key: k, Val: obj.Map[k]})
		}
	case map[string]any:
		for k, val := range obj {
			entries = append(entries, Entry{Key: k, Val: val})
		}
	}
	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Key < entries[j].Key
	})
	return entries
}

func Compare(a, b any) int {
	ta, tb := TypeOrder(a), TypeOrder(b)
	if ta != tb {
		if ta < tb {
			return -1
		}
		return 1
	}
	switch ta {
	case 0:
		return 0
	case 1:
		ba, bb := a.(bool), b.(bool)
		if ba == bb {
			return 0
		}
		if !ba && bb {
			return -1
		}
		return 1
	case 2:
		fa, fb := ToFloat(a), ToFloat(b)
		if fa < fb {
			return -1
		}
		if fa > fb {
			return 1
		}
		return 0
	case 3:
		sa, sb := a.(string), b.(string)
		if sa < sb {
			return -1
		}
		if sa > sb {
			return 1
		}
		return 0
	case 4:
		aa, ab := a.([]any), b.([]any)
		minLen := len(aa)
		if len(ab) < minLen {
			minLen = len(ab)
		}
		for i := 0; i < minLen; i++ {
			cmp := Compare(aa[i], ab[i])
			if cmp != 0 {
				return cmp
			}
		}
		if len(aa) < len(ab) {
			return -1
		}
		if len(aa) > len(ab) {
			return 1
		}
		return 0
	case 5:
		oa, ob := GetSortedEntries(a), GetSortedEntries(b)
		minLen := len(oa)
		if len(ob) < minLen {
			minLen = len(ob)
		}
		for i := 0; i < minLen; i++ {
			if oa[i].Key < ob[i].Key {
				return -1
			}
			if oa[i].Key > ob[i].Key {
