	if tok.Type == TokIdent {
		p.next()
		name := tok.Str
		var args []ASTNode
		if p.peek().Type == TokPunct && p.peek().Str == "(" {
			p.next()
			for {
				if p.peek().Type == TokPunct && p.peek().Str == ")" {
					break
				}
				arg, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				args = append(args, arg)
				if p.peek().Type == TokOp && p.peek().Str == ";" {
					p.next()
				} else {
					break
				}
			}
			_, err := p.expect(TokPunct, ")")
			if err != nil {
				return nil, err
			}
