			}
			continue
		}

		if l.match("..") {
			tokens = append(tokens, Token{Type: TokOp, Str: "..", Line: line, Col: col})
			continue
		}
		if l.match("//=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "//=", Line: line, Col: col})
			continue
		}
		if l.match("//") {
			tokens = append(tokens, Token{Type: TokOp, Str: "//", Line: line, Col: col})
			continue
		}
		if l.match("==") {
			tokens = append(tokens, Token{Type: TokOp, Str: "==", Line: line, Col: col})
			continue
		}
		if l.match("!=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "!=", Line: line, Col: col})
			continue
		}
		if l.match("<=") {
