			case "--raw-output":
				opts.Raw = true
			case "--raw-output0":
				opts.Raw = true
				opts.NullTerm = true
			case "--join-output":
				opts.Raw = true
				opts.Join = true
			case "--ascii-output":
				opts.ASCII = true
			case "--sort-keys":
				opts.SortKeys = true
			case "--color-output":
				opts.Color = true
			case "--monochrome-output":
				opts.Color = false
			case "--tab":
				opts.Indent = -1
			case "--exit-status":
				exitStatusFlag = true
			case "--unbuffered":
				unbuffered = true
			case "--seq":
				opts.Seq = true
			case "--indent":
				i++
				if i >= len(args) {
					fmt.Fprintf(os.Stderr, "jq: option --indent requires an argument\n")
					os.Exit(2)
				}
				n, err := strconv.Atoi(args[i])
				if err != nil || n < -1 || n > 7 {
					fmt.Fprintf(os.Stderr, "jq: --indent takes a number between -1 and 7\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n")
					os.Exit(2)
				}
				opts.Indent = n
			case "--from-file":
				i++
				if i >= len(args) {
					fmt.Fprintf(os.Stderr, "jq: option -f requires an argument\n")
					os.Exit(2)
				}
				filterFile = args[i]
			case "--library-path":
				i++
			case "--arg":
				if i+2 >= len(args) {
					fmt.Fprintf(os.Stderr, "jq: option --arg requires two arguments\n")
					os.Exit(2)
				}
				name := args[i+1]
				val := args[i+2]
				namedArgs.Set(name, val)
				i += 2
			case "--argjson":
				if i+2 >= len(args) {
					fmt.Fprintf(os.Stderr, "jq: option --argjson requires two arguments\n")
					os.Exit(2)
				}
				name := args[i+1]
				jsonText := args[i+2]
				dec := json.NewDecoder(strings.NewReader(jsonText))
				dec.UseNumber()
				val, err := decodeJSON(dec)
				if err != nil {
					fmt.Fprintf(os.Stderr, "jq: invalid JSON text passed to --argjson\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n")
					os.Exit(2)
				}
				namedArgs.Set(name, val)
				i += 2
			case "--slurpfile":
				if i+2 >= len(args) {
					fmt.Fprintf(os.Stderr, "jq: option --slurpfile requires two arguments\n")
					os.Exit(2)
				}
				name := args[i+1]
				fileName := args[i+2]
				content, err := os.ReadFile(fileName)
				if err != nil {
					fmt.Fprintf(os.Stderr, "jq: Bad JSON in --slurpfile %s %s: Could not open %s: No such file or directory\n", name, fileName, fileName)
					os.Exit(2)
				}
				dec := json.NewDecoder(bytes.NewReader(content))
				dec.UseNumber()
				var arr []any
				for {
					val, err := decodeJSON(dec)
					if err == io.EOF {
						break
					}
					if err != nil {
						fmt.Fprintf(os.Stderr, "jq: Bad JSON in --slurpfile %s %s\n", name, fileName)
						os.Exit(2)
					}
					arr = append(arr, val)
				}
				namedArgs.Set(name, arr)
				i += 2
			case "--rawfile":
				if i+2 >= len(args) {
					fmt.Fprintf(os.Stderr, "jq: option --rawfile requires two arguments\n")
					os.Exit(2)
				}
				name := args[i+1]
				fileName := args[i+2]
				content, err := os.ReadFile(fileName)
				if err != nil {
					fmt.Fprintf(os.Stderr, "jq: Bad JSON in --rawfile %s %s: Could not open %s: No such file or directory\n", name, fileName, fileName)
					os.Exit(2)
				}
				namedArgs.Set(name, string(content))
				i += 2
			default:
				fmt.Fprintf(os.Stderr, "jq: Unknown option %s\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", arg)
				os.Exit(2)
			}
			i++
			continue
		}

		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			if _, err := strconv.ParseFloat(arg, 64); err == nil {
				if filterStr == "" && filterFile == "" {
					filterStr = arg
				} else {
					inputFiles = append(inputFiles, arg)
				}
				i++
				continue
			}

			flags := arg[1:]
			consumedNext := false
			for j, ch := range flags {
				switch ch {
				case 'n':
					nullInput = true
				case 'R':
					rawInput = true
				case 's':
					slurpInput = true
				case 'c':
					opts.Compact = true
				case 'r':
					opts.Raw = true
				case 'j':
					opts.Raw = true
					opts.Join = true
				case 'a':
					opts.ASCII = true
				case 'S':
					opts.SortKeys = true
				case 'C':
					opts.Color = true
				case 'M':
					opts.Color = false
				case 'e':
					exitStatusFlag = true
				case 'f':
					if j == len(flags)-1 {
						i++
						if i >= len(args) {
							fmt.Fprintf(os.Stderr, "jq: option -f requires an argument\n")
							os.Exit(2)
						}
						filterFile = args[i]
						consumedNext = true
					}
				case 'L':
					if j == len(flags)-1 {
						i++
						consumedNext = true
					}
				default:
					fmt.Fprintf(os.Stderr, "jq: Unknown option -%c\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", ch)
					os.Exit(2)
				}
			}
			i++
			if consumedNext {
				// already advanced
			}
			continue
		}

		if filterStr == "" && filterFile == "" {
			filterStr = arg
		} else {
			inputFiles = append(inputFiles, arg)
		}
		i++
	}

	for i < len(args) {
		if filterStr == "" && filterFile == "" {
			filterStr = args[i]
		} else {
			inputFiles = append(inputFiles, args[i])
		}
		i++
	}

	if filterFile != "" {
		content, err := os.ReadFile(filterFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "jq: error: Could not open file %s: No such file or directory\n", filterFile)
			os.Exit(2)
		}
		filterStr = string(content)
	}

	if filterStr == "" {
		filterStr = "."
	}

	baseCtx, err := InitBaseContext()
	if err != nil {
		fmt.Fprintf(os.Stderr, "jq: error: %v\n", err)
		os.Exit(3)
	}

	argsObj := NewJqObject()
	argsObj.Set("positional", positionalArgs)
	argsObj.Set("named", namedArgs)
	baseCtx.SetVar("$ARGS", argsObj)

	for _, k := range namedArgs.Keys {
		baseCtx.SetVar("$"+k, namedArgs.Map[k])
	}

	ast, err := ParseFilter(filterStr)
	if err != nil {
		fmt.Fprintf(os.Stderr, "jq: error: %v\n", err)
		os.Exit(3)
	}

	var inputs []any

	if nullInput {
		inputs = []any{nil}
	} else if len(inputFiles) > 0 {
		fileErrorOccurred := false
		for _, fileName := range inputFiles {
			file, err := os.Open(fileName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "jq: error: Could not open file %s: No such file or directory\n", fileName)
				fileErrorOccurred = true
				continue
			}
			readInputs(file, rawInput, slurpInput, &inputs)
			file.Close()
		}
		if fileErrorOccurred && len(inputs) == 0 {
			os.Exit(2)
		}
	} else {
		readInputs(os.Stdin, rawInput, slurpInput, &inputs)
	}

	if slurpInput && !nullInput {
		inputs = []any{inputs}
	}

	outputCount := 0
	var lastOutput any
	runtimeError := false

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	emitOutput := func(v any) error {
		outputCount++
		lastOutput = v

		if opts.Seq {
			writer.WriteByte(0x1e)
		}

		if opts.Raw {
			if s, isStr := v.(string); isStr {
				writer.WriteString(s)
			} else {
				writer.WriteString(FormatValue(v, opts))
			}
			if opts.NullTerm {
				writer.WriteByte(0x00)
			} else if !opts.Join {
				writer.WriteByte('\n')
			}
		} else {
			writer.WriteString(FormatValue(v, opts))
			writer.WriteByte('\n')
		}

		if unbuffered {
			writer.Flush()
		}
		return nil
	}

	for _, inVal := range inputs {
		err := Eval(ast, baseCtx, inVal, emitOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "jq: error (at <unknown>): %v\n", err)
			runtimeError = true
			break
		}
	}

	writer.Flush()

	if runtimeError {
		os.Exit(5)
	}

	if exitStatusFlag {
		if outputCount == 0 {
			os.Exit(4)
		}
		if !IsTruthy(lastOutput) {
			os.Exit(1)
		}
		os.Exit(0)
	}
}

func readInputs(r io.Reader, rawInput, slurpInput bool, inputs *[]any) {
	if rawInput {
		if slurpInput {
			content, err := io.ReadAll(r)
			if err == nil {
				*inputs = append(*inputs, string(content))
			}
		} else {
			scanner := bufio.NewScanner(r)
			for scanner.Scan() {
				*inputs = append(*inputs, scanner.Text())
			}
		}
	} else {
		dec := json.NewDecoder(r)
		dec.UseNumber()
		for {
			val, err := decodeJSON(dec)
			if err == io.EOF {
				break
			}
			if err != nil {
				break
			}
			*inputs = append(*inputs, val)
		}
	}
}
EOF"}

