	} else if len(inputFiles) > 0 {
		fileErrorOccurred := false
		for _, fileName := range inputFiles {
			file, err := os.Open(fileName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "jq: error: Could not open file %s: No such file or directory\n", fileName)
				fileErrorOccurred = true
				continue
			}
			readInputs(file, rawInput, slurpInput, &inputs)
			file.Close()
		}
		if fileErrorOccurred && len(inputs) == 0 {
			os.Exit(2)
		}
	} else {
		readInputs(os.Stdin, rawInput, slurpInput, &inputs)
	}

	if slurpInput && !nullInput {
		inputs = []any{inputs}
	}

	outputCount := 0
	var lastOutput any
	runtimeError := false

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	emitOutput := func(v any) error {
		outputCount++
		lastOutput = v

		if opts.Seq {
			writer.WriteByte(0x1e)
		}

		if opts.Raw {
			if s, isStr := v.(string); isStr {
				writer.WriteString(s)
			} else {
				writer.WriteString(FormatValue(v, opts))
			}
			if opts.NullTerm {
				writer.WriteByte(0x00)
			} else if !opts.Join {
				writer.WriteByte('\n')
			}
		} else {
			writer.WriteString(FormatValue(v, opts))
			writer.WriteByte('\n')
		}

		if unbuffered {
			writer.Flush()
		}
		return nil
	}

	for _, inVal := range inputs {
		err := Eval(ast, baseCtx, inVal, emitOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "jq: error (at <unknown>): %v\n", err)
			runtimeError = true
			break
		}
	}

	writer.Flush()

	if runtimeError {
		os.Exit(5)
	}

	if exitStatusFlag {
		if outputCount == 0 {
			os.Exit(4)
		}
		if !IsTruthy(lastOutput) {
			os.Exit(1)
		}
		os.Exit(0)
	}
}

func readInputs(r io.Reader, rawInput, slurpInput bool, inputs *[]any) {
	if rawInput {
		if slurpInput {
			content, err := io.ReadAll(r)
			if err == nil {
				*inputs = append(*inputs, string(content))
			}
		} else {
			scanner := bufio.NewScanner(r)
			for scanner.Scan() {
				*inputs = append(*inputs, scanner.Text())
			}
		}
	} else {
		dec := json.NewDecoder(r)
		dec.UseNumber()
		for {
			val, err := decodeJSON(dec)
			if err == io.EOF {
				break
			}
			if err != nil {
				break
			}
			*inputs = append(*inputs, val)
		}
	}
}
EOF"}

{"command":"cat <<'EOF' > lexer.go
package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type TokenType int

const (
	TokEOF TokenType = iota
	TokNumber
	TokString
	TokIdent
	TokVar
	TokKeyword
	TokOp
	TokPunct
	TokFormat
)

type Token struct {
	Type  TokenType
	Str   string
	Num   float64
	Parts []StrPart
	Line  int
	Col   int
}

type StrPart struct {
	IsExpr bool
	Str    string
	Expr   []Token
}

type Lexer struct {
	src  string
	pos  int
	line int
	col  int
}

func NewLexer(src string) *Lexer {
	return &Lexer{src: src, line: 1, col: 1}
}

func (l *Lexer) peek() rune {
	if l.pos >= len(l.src) {
		return 0
	}
	r, _ := utf8.DecodeRuneInString(l.src[l.pos:])
	return r
}

func (l *Lexer) next() rune {
	if l.pos >= len(l.src) {
		return 0
	}
	r, w := utf8.DecodeRuneInString(l.src[l.pos:])
	l.pos += w
	if r == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return r
}

func (l *Lexer) skipWhitespaceAndComments() {
	for {
		r := l.peek()
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' {
			l.next()
		} else if r == '#' {
			for r != 0 && r != '\n' {
				r = l.next()
			}
		} else {
			break
		}
	}
}

func (l *Lexer) Tokenize() ([]Token, error) {
	var tokens []Token
	for {
		l.skipWhitespaceAndComments()
		if l.pos >= len(l.src) {
			tokens = append(tokens, Token{Type: TokEOF, Line: l.line, Col: l.col})
			break
		}

		line, col := l.line, l.col
		r := l.peek()

		if r == '"' {
			tok, err := l.readString()
			if err != nil {
				return nil, err
			}
			tok.Line = line
			tok.Col = col
			tokens = append(tokens, tok)
			continue
		}

		if r == '@' {
			l.next()
			start := l.pos
			for isIdentChar(l.peek()) {
				l.next()
			}
			name := l.src[start:l.pos]
			tokens = append(tokens, Token{Type: TokFormat, Str: "@" + name, Line: line, Col: col})
			continue
		}

		if r == '$' {
			l.next()
			start := l.pos
			for isIdentChar(l.peek()) {
				l.next()
			}
			name := l.src[start:l.pos]
			tokens = append(tokens, Token{Type: TokVar, Str: "$" + name, Line: line, Col: col})
			continue
		}

		if unicode.IsDigit(r) {
			tok, err := l.readNumber()
			if err != nil {
				return nil, err
			}
			tok.Line = line
			tok.Col = col
			tokens = append(tokens, tok)
			continue
		}

		if isIdentStart(r) {
			start := l.pos
			for isIdentChar(l.peek()) {
				l.next()
			}
			word := l.src[start:l.pos]
			if isKeyword(word) {
				tokens = append(tokens, Token{Type: TokKeyword, Str: word, Line: line, Col: col})
			} else {
				tokens = append(tokens, Token{Type: TokIdent, Str: word, Line: line, Col: col})
			}
			continue
		}

		if l.match("..") {
			tokens = append(tokens, Token{Type: TokOp, Str: "..", Line: line, Col: col})
			continue
		}
		if l.match("//=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "//=", Line: line, Col: col})
			continue
		}
		if l.match("//") {
			tokens = append(tokens, Token{Type: TokOp, Str: "//", Line: line, Col: col})
			continue
		}
		if l.match("==") {
			tokens = append(tokens, Token{Type: TokOp, Str: "==", Line: line, Col: col})
			continue
		}
		if l.match("!=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "!=", Line: line, Col: col})
			continue
		}
		if l.match("<=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "<=", Line: line, Col: col})
			continue
		}
		if l.match(">=") {
			tokens = append(tokens, Token{Type: TokOp, Str: ">=", Line: line, Col: col})
			continue
		}
		if l.match("|=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "|=", Line: line, Col: col})
			continue
		}
		if l.match("+=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "+=", Line: line, Col: col})
			continue
		}
		if l.match("-=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "-=", Line: line, Col: col})
			continue
		}
		if l.match("*=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "*=", Line: line, Col: col})
			continue
		}
		if l.match("/=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "/=", Line: line, Col: col})
			continue
		}
		if l.match("%=") {
			tokens = append(tokens, Token{Type: TokOp, Str: "%=", Line: line, Col: col})
			continue
		}

		ch := l.next()
		chStr := string(ch)
		if strings.ContainsRune("()[]{}", ch) {
			tokens = append(tokens, Token{Type: TokPunct, Str: chStr, Line: line, Col: col})
		} else if strings.ContainsRune(".|,;:?=+=-*/%<>", ch) {
			tokens = append(tokens, Token{Type: TokOp, Str: chStr, Line: line, Col: col})
		} else {
			return nil, fmt.Errorf("unexpected character %q at line %d, column %d", ch, line, col)
		}
	}
	return tokens, nil
}

func (l *Lexer) match(prefix string) bool {
	if strings.HasPrefix(l.src[l.pos:], prefix) {
		for range prefix {
			l.next()
		}
		return true
	}
	return false
}

func (l *Lexer) readNumber() (Token, error) {
	start := l.pos
	for unicode.IsDigit(l.peek()) {
		l.next()
	}
	if l.peek() == '.' {
		l.next()
		for unicode.IsDigit(l.peek()) {
			l.next()
		}
	}
	if l.peek() == 'e' || l.peek() == 'E' {
		l.next()
		if l.peek() == '+' || l.peek() == '-' {
			l.next()
		}
		for unicode.IsDigit(l.peek()) {
			l.next()
		}
	}
	numStr := l.src[start:l.pos]
	num, err := strconv.ParseFloat(numStr, 64)
	if err != nil {
		return Token{}, fmt.Errorf("invalid number %q", numStr)
	}
	return Token{Type: TokNumber, Num: num, Str: numStr}, nil
}

func (l *Lexer) readString() (Token, error) {
	l.next() // consume initial "
	var parts []StrPart
	var currentBuf strings.Builder

	for {
		if l.pos >= len(l.src) {
			return Token{}, fmt.Errorf("unterminated string")
		}
		r := l.next()
		if r == '"' {
			if currentBuf.Len() > 0 || len(parts) == 0 {
				parts = append(parts, StrPart{Str: currentBuf.String()})
			}
			break
		}
		if r == '\\' {
			if l.pos >= len(l.src) {
				return Token{}, fmt.Errorf("unterminated string escape")
			}
			r2 := l.peek()
			if r2 == '(' {
				l.next()
				if currentBuf.Len() > 0 {
					parts = append(parts, StrPart{Str: currentBuf.String()})
					currentBuf.Reset()
				}
				exprTokens, err := l.readStringInterpExpr()
				if err != nil {
					return Token{}, err
				}
				parts = append(parts, StrPart{IsExpr: true, Expr: exprTokens})
				continue
			}
			l.next()
			switch r2 {
			case '"':
				currentBuf.WriteByte('"')
			case '\\':
				currentBuf.WriteByte('\\')
			case '/':
				currentBuf.WriteByte('/')
			case 'b':
				currentBuf.WriteByte('\b')
			case 'f':
				currentBuf.WriteByte('\f')
			case 'n':
				currentBuf.WriteByte('\n')
			case 'r':
				currentBuf.WriteByte('\r')
			case 't':
				currentBuf.WriteByte('\t')
			case 'u':
				hexStr := ""
				for i := 0; i < 4; i++ {
					hexStr += string(l.next())
				}
				code, err := strconv.ParseInt(hexStr, 16, 32)
				if err != nil {
					return Token{}, fmt.Errorf("invalid hex escape \\u%s", hexStr)
				}
				currentBuf.WriteRune(rune(code))
			default:
				return Token{}, fmt.Errorf("Invalid escape at line %d, column %d", l.line, l.col)
			}
		} else {
			currentBuf.WriteRune(r)
		}
	}
	return Token{Type: TokString, Parts: parts}, nil
}

func (l *Lexer) readStringInterpExpr() ([]Token, error) {
	parenDepth := 1
	startPos := l.pos
	for parenDepth > 0 && l.pos < len(l.src) {
		r := l.peek()
		if r == '"' {
			l.readString()
			continue
		}
		if r == '(' {
			parenDepth++
		} else if r == ')' {
			parenDepth--
			if parenDepth == 0 {
				exprSrc := l.src[startPos:l.pos]
				l.next()
				subLexer := NewLexer(exprSrc)
				return subLexer.Tokenize()
			}
		}
		l.next()
	}
	if parenDepth > 0 {
		return nil, fmt.Errorf("unterminated string interpolation")
	}
	return nil, nil
}

func isIdentStart(r rune) bool {
	return unicode.IsLetter(r) || r == '_'
}

func isIdentChar(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_'
}

func isKeyword(s string) bool {
	keywords := map[string]bool{
		"if": true, "then": true, "elif": true, "else": true, "end": true,
		"and": true, "or": true, "as": true, "def": true,
		"reduce": true, "foreach": true, "try": true, "catch": true,
		"label": true, "break": true, "empty": true, "true": true,
		"false": true, "null": true,
	}
	return keywords[s]
}
EOF"}

