type TokenType int

const (
	TokEOF TokenType = iota
	TokNumber
	TokString
	TokIdent
	TokVar
	TokKeyword
	TokOp
	TokPunct
	TokFormat
)

type Token struct {
	Type  TokenType
	Str   string
	Num   float64
	Parts []StrPart
	Line  int
	Col   int
}

type StrPart struct {
	IsExpr bool
	Str    string
	Expr   []Token
}

type Lexer struct {
	src  string
	pos  int
	line int
	col  int
}

func NewLexer(src string) *Lexer {
	return &Lexer{src: src, line: 1, col: 1}
}

func (l *Lexer) peek() rune {
	if l.pos >= len(l.src) {
		return 0
	}
	r, _ := utf8.DecodeRuneInString(l.src[l.pos:])
	return r
}

func (l *Lexer) next() rune {
	if l.pos >= len(l.src) {
		return 0
	}
	r, w := utf8.DecodeRuneInString(l.src[l.pos:])
	l.pos += w
	if r == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return r
}

func (l *Lexer) skipWhitespaceAndComments() {
	for {
		r := l.peek()
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' {
			l.next()
		} else if r == '#' {
			for r != 0 && r != '\n' {
				r = l.next()
			}
		} else {
			break
		}
	}
}

func (l *Lexer) Tokenize() ([]Token, error) {
