			break
		}

		line, col := l.line, l.col
		r := l.peek()

		if r == '"' {
			tok, err := l.readString()
			if err != nil {
				return nil, err
			}
			tok.Line = line
			tok.Col = col
			tokens = append(tokens, tok)
			continue
