package main

import (
	"fmt"
)

type Parser struct {
	tokens []Token
	pos    int
}

func NewParser(tokens []Token) *Parser {
	return &Parser{tokens: tokens, pos: 0}
}

func (p *Parser) peek() Token {
	if p.pos >= len(p.tokens) {
		return Token{Type: TokEOF}
	}
	return p.tokens[p.pos]
}

func (p *Parser) next() Token {
	tok := p.peek()
	if p.pos < len(p.tokens) {
		p.pos++
	}
	return tok
}

func (p *Parser) match(tp TokenType, str string) bool {
	tok := p.peek()
	if tok.Type == tp && (str == "" || tok.Str == str) {
		p.next()
		return true
	}
	return false
}

func (p *Parser) expect(tp TokenType, str string) (Token, error) {
	tok := p.peek()
	if tok.Type == tp && (str == "" || tok.Str == str) {
		p.next()
		return tok, nil
	}
	return tok, fmt.Errorf("syntax error, unexpected %s %q at line %d, column %d", formatTokenType(tok.Type), tok.Str, tok.Line, tok.Col)
}

func formatTokenType(tp TokenType) string {
	switch tp {
	case TokEOF:
		return "end of file"
	case TokIdent:
		return "IDENT"
	case TokKeyword:
		return "keyword"
	case TokNumber:
		return "NUMBER"
	case TokString:
		return "STRING"
	case TokOp:
		return "operator"
	case TokPunct:
		return "punctuation"
	case TokVar:
		return "VARIABLE"
	}
	return "token"
}

func ParseFilter(src string) (ASTNode, error) {
	lexer := NewLexer(src)
	tokens, err := lexer.Tokenize()
	if err != nil {
		return nil, err
	}
	parser := NewParser(tokens)
	ast, err := parser.Parse()
	if err != nil {
		return nil, err
	}
	if parser.peek().Type != TokEOF {
		tok := parser.peek()
		return nil, fmt.Errorf("syntax error, unexpected %s %q at line %d, column %d", formatTokenType(tok.Type), tok.Str, tok.Line, tok.Col)
	}
	return ast, nil
}

func (p *Parser) Parse() (ASTNode, error) {
	return p.parseDef()
}

func (p *Parser) parseDef() (ASTNode, error) {
	if p.peek().Type == TokKeyword && p.peek().Str == "def" {
		p.next()
		nameTok, err := p.expect(TokIdent, "")
		if err != nil {
			return nil, err
		}
		var params []string
		if p.peek().Type == TokPunct && p.peek().Str == "(" {
			p.next()
			for {
				pTok, err := p.expect(TokIdent, "")
				if err != nil {
					return nil, err
				}
				params = append(params, pTok.Str)
				if p.peek().Type == TokOp && p.peek().Str == ";" {
					p.next()
				} else {
					break
				}
			}
			_, err = p.expect(TokPunct, ")")
			if err != nil {
				return nil, err
			}
		}
		_, err = p.expect(TokOp, ":")
		if err != nil {
			return nil, err
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		_, err = p.expect(TokOp, ";")
		if err != nil {
			return nil, err
		}
		if p.peek().Type == TokEOF {
			return &FuncDefExpr{Name: nameTok.Str, Params: params, Body: body, Next: nil}, nil
		}
		next, err := p.parseDef()
		if err != nil {
			return nil, err
		}
		return &FuncDefExpr{Name: nameTok.Str, Params: params, Body: body, Next: next}, nil
	}
	return p.parsePipe()
}

func (p *Parser) parsePipe() (ASTNode, error) {
	left, err := p.parseComma()
	if err != nil {
		return nil, err
	}
	for p.peek().Type == TokOp && p.peek().Str == "|" {
		p.next()
		right, err := p.parseComma()
		if err != nil {
			return nil, err
		}
		left = &PipeExpr{Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseComma() (ASTNode, error) {
	left, err := p.parseVarBind()
	if err != nil {
		return nil, err
	}
	for p.peek().Type == TokOp && p.peek().Str == "," {
		p.next()
		right, err := p.parseVarBind()
		if err != nil {
			return nil, err
		}
		left = &CommaExpr{Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseVarBind() (ASTNode, error) {
	left, err := p.parseAssign()
	if err != nil {
		return nil, err
	}
	if p.peek().Type == TokKeyword && p.peek().Str == "as" {
		p.next()
		pattern, err := p.parsePattern()
		if err != nil {
			return nil, err
		}
		_, err = p.expect(TokOp, "|")
		if err != nil {
			return nil, err
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &VarBindExpr{Expr: left, Pattern: pattern, Body: body}, nil
	}
	return left, nil
}

func (p *Parser) parseAssign() (ASTNode, error) {
	left, err := p.parseAlternative()
	if err != nil {
		return nil, err
	}
	tok := p.peek()
	if tok.Type == TokOp {
		switch tok.Str {
		case "=":
			p.next()
			right, err := p.parseAssign()
			if err != nil {
				return nil, err
			}
			return &AssignExpr{Path: left, Val: right}, nil
		case "|=":
			p.next()
			right, err := p.parseAssign()
			if err != nil {
				return nil, err
			}
			return &UpdateExpr{Path: left, Val: right}, nil
		case "+=", "-=", "*=", "/=", "%=", "//=":
			p.next()
			right, err := p.parseAssign()
			if err != nil {
				return nil, err
			}
			return &OpAssignExpr{Op: tok.Str, Path: left, Val: right}, nil
		}
	}
	return left, nil
}

func (p *Parser) parseAlternative() (ASTNode, error) {
	left, err := p.parseLogicalOr()
	if err != nil {
		return nil, err
	}
	for p.peek().Type == TokOp && p.peek().Str == "//" {
		p.next()
		right, err := p.parseLogicalOr()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: "//", Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseLogicalOr() (ASTNode, error) {
	left, err := p.parseLogicalAnd()
	if err != nil {
		return nil, err
	}
	for p.peek().Type == TokKeyword && p.peek().Str == "or" {
		p.next()
		right, err := p.parseLogicalAnd()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: "or", Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseLogicalAnd() (ASTNode, error) {
	left, err := p.parseComparison()
	if err != nil {
		return nil, err
	}
	for p.peek().Type == TokKeyword && p.peek().Str == "and" {
		p.next()
		right, err := p.parseComparison()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: "and", Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseComparison() (ASTNode, error) {
	left, err := p.parseAdditive()
	if err != nil {
		return nil, err
	}
	for p.peek().Type == TokOp {
		op := p.peek().Str
		if op == "==" || op == "!=" || op == "<" || op == "<=" || op == ">" || op == ">=" {
			p.next()
			right, err := p.parseAdditive()
			if err != nil {
				return nil, err
			}
			left = &BinaryExpr{Op: op, Left: left, Right: right}
		} else {
			break
		}
	}
	return left, nil
}

func (p *Parser) parseAdditive() (ASTNode, error) {
	left, err := p.parseMultiplicative()
	if err != nil {
		return nil, err
	}
	for p.peek().Type == TokOp && (p.peek().Str == "+" || p.peek().Str == "-") {
		op := p.peek().Str
		p.next()
		right, err := p.parseMultiplicative()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: op, Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseMultiplicative() (ASTNode, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for p.peek().Type == TokOp && (p.peek().Str == "*" || p.peek().Str == "/" || p.peek().Str == "%") {
		op := p.peek().Str
		p.next()
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		left = &BinaryExpr{Op: op, Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseUnary() (ASTNode, error) {
	tok := p.peek()
	if tok.Type == TokFormat {
		p.next()
		peekTok := p.peek()
		if peekTok.Type == TokEOF || (peekTok.Type == TokOp && (peekTok.Str == "," || peekTok.Str == "|")) || (peekTok.Type == TokPunct && (peekTok.Str == ")" || peekTok.Str == "]" || peekTok.Str == "}")) || (peekTok.Type == TokKeyword && (peekTok.Str == "then" || peekTok.Str == "else" || peekTok.Str == "end")) {
			return &FormatExpr{Fmt: tok.Str, Target: nil}, nil
		}
		target, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &FormatExpr{Fmt: tok.Str, Target: target}, nil
	}
	if tok.Type == TokOp && (tok.Str == "-" || tok.Str == "+") {
		p.next()
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &UnaryExpr{Op: tok.Str, Right: right}, nil
	}
	if tok.Type == TokKeyword && tok.Str == "try" {
		p.next()
		body, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		var catch ASTNode
		if p.peek().Type == TokKeyword && p.peek().Str == "catch" {
			p.next()
			catch, err = p.parseUnary()
			if err != nil {
				return nil, err
			}
		}
		return &TryExpr{Body: body, Catch: catch}, nil
	}
	if tok.Type == TokKeyword && tok.Str == "if" {
		return p.parseIf()
	}
	if tok.Type == TokKeyword && tok.Str == "reduce" {
		return p.parseReduce()
	}
	if tok.Type == TokKeyword && tok.Str == "foreach" {
		return p.parseForeach()
	}
	if tok.Type == TokKeyword && tok.Str == "label" {
		p.next()
		vTok, err := p.expect(TokVar, "")
		if err != nil {
			return nil, err
		}
		_, err = p.expect(TokOp, "|")
		if err != nil {
			return nil, err
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &LabelExpr{Name: vTok.Str, Body: body}, nil
	}
	if tok.Type == TokKeyword && tok.Str == "break" {
		p.next()
		vTok, err := p.expect(TokVar, "")
		if err != nil {
			return nil, err
		}
		return &BreakExpr{Name: vTok.Str}, nil
	}

	return p.parsePostfix()
}

func (p *Parser) parseIf() (ASTNode, error) {
	p.next()
	cond, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	_, err = p.expect(TokKeyword, "then")
	if err != nil {
		return nil, err
	}
	thenBody, err := p.parsePipe()
	if err != nil {
		return nil, err
	}

	var elifs []ElifClause
	for p.peek().Type == TokKeyword && p.peek().Str == "elif" {
		p.next()
		eCond, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		_, err = p.expect(TokKeyword, "then")
		if err != nil {
			return nil, err
		}
		eThen, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		elifs = append(elifs, ElifClause{Cond: eCond, Then: eThen})
	}

	var elseBody ASTNode
	if p.peek().Type == TokKeyword && p.peek().Str == "else" {
		p.next()
		elseBody, err = p.parsePipe()
		if err != nil {
			return nil, err
		}
	}
	_, err = p.expect(TokKeyword, "end")
	if err != nil {
		return nil, err
	}
	return &IfExpr{Cond: cond, Then: thenBody, Elifs: elifs, Else: elseBody}, nil
}

func (p *Parser) parseReduce() (ASTNode, error) {
	p.next()
	expr, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	_, err = p.expect(TokKeyword, "as")
	if err != nil {
		return nil, err
	}
	pattern, err := p.parsePattern()
	if err != nil {
		return nil, err
	}
	_, err = p.expect(TokPunct, "(")
	if err != nil {
		return nil, err
	}
	init, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	_, err = p.expect(TokOp, ";")
	if err != nil {
		return nil, err
	}
	update, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	_, err = p.expect(TokPunct, ")")
	if err != nil {
		return nil, err
	}
	return &ReduceExpr{Expr: expr, Pattern: pattern, Init: init, Update: update}, nil
}

func (p *Parser) parseForeach() (ASTNode, error) {
	p.next()
	expr, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	_, err = p.expect(TokKeyword, "as")
	if err != nil {
		return nil, err
	}
	pattern, err := p.parsePattern()
	if err != nil {
		return nil, err
	}
	_, err = p.expect(TokPunct, "(")
	if err != nil {
		return nil, err
	}
	init, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	_, err = p.expect(TokOp, ";")
	if err != nil {
		return nil, err
	}
	update, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	var extract ASTNode
	if p.peek().Type == TokOp && p.peek().Str == ";" {
		p.next()
		extract, err = p.parsePipe()
		if err != nil {
			return nil, err
		}
	}
	_, err = p.expect(TokPunct, ")")
	if err != nil {
		return nil, err
	}
	return &ForeachExpr{Expr: expr, Pattern: pattern, Init: init, Update: update, Extract: extract}, nil
}

func (p *Parser) parsePattern() (PatternAST, error) {
	tok := p.peek()
	if tok.Type == TokVar {
		p.next()
		return PatternAST{VarName: tok.Str}, nil
	}
	if tok.Type == TokPunct && tok.Str == "[" {
		p.next()
		var arr []PatternAST
		for {
			if p.peek().Type == TokPunct && p.peek().Str == "]" {
				break
			}
			pat, err := p.parsePattern()
			if err != nil {
				return PatternAST{}, err
			}
			arr = append(arr, pat)
			if p.peek().Type == TokOp && p.peek().Str == "," {
				p.next()
			} else {
				break
			}
		}
		_, err := p.expect(TokPunct, "]")
		if err != nil {
			return PatternAST{}, err
		}
		return PatternAST{Array: arr}, nil
	}
	if tok.Type == TokPunct && tok.Str == "{" {
		p.next()
		var fields []ObjPatternField
		for {
			if p.peek().Type == TokPunct && p.peek().Str == "}" {
				break
			}
			kTok, err := p.expect(TokIdent, "")
			if err != nil {
				return PatternAST{}, err
			}
			var pat PatternAST
			if p.peek().Type == TokOp && p.peek().Str == ":" {
				p.next()
				pat, err = p.parsePattern()
				if err != nil {
					return PatternAST{}, err
				}
			} else {
				pat = PatternAST{VarName: "$" + kTok.Str}
			}
			fields = append(fields, ObjPatternField{Key: kTok.Str, Pattern: pat})
			if p.peek().Type == TokOp && p.peek().Str == "," {
				p.next()
			} else {
				break
			}
		}
		_, err := p.expect(TokPunct, "}")
		if err != nil {
			return PatternAST{}, err
		}
		return PatternAST{ObjFields: fields}, nil
	}
	return PatternAST{}, fmt.Errorf("invalid pattern %q", tok.Str)
}

func (p *Parser) parsePostfix() (ASTNode, error) {
	node, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}

	for {
		tok := p.peek()
		if tok.Type == TokOp && tok.Str == "." {
			p.next()
			fieldTok := p.peek()
			if fieldTok.Type == TokIdent {
				p.next()
				opt := p.match(TokOp, "?")
				node = &FieldExpr{Target: node, Key: &StrExpr{Parts: []StrPartAST{{Str: fieldTok.Str}}}, Opt: opt}
			} else if fieldTok.Type == TokString {
				p.next()
				opt := p.match(TokOp, "?")
				sExpr, err := p.parseStrExpr(fieldTok)
				if err != nil {
					return nil, err
				}
				node = &FieldExpr{Target: node, Key: sExpr, Opt: opt}
			} else if fieldTok.Type == TokPunct && fieldTok.Str == "[" {
				// handled below
			} else {
				node = &FieldExpr{Target: node, Key: &IdentityExpr{}}
			}
		} else if tok.Type == TokPunct && tok.Str == "[" {
			p.next()
			if p.peek().Type == TokPunct && p.peek().Str == "]" {
				p.next()
				opt := p.match(TokOp, "?")
				node = &IterExpr{Target: node, Opt: opt}
			} else if p.peek().Type == TokOp && p.peek().Str == ":" {
				p.next()
				var endAST ASTNode
				if !(p.peek().Type == TokPunct && p.peek().Str == "]") {
					var err error
					endAST, err = p.parsePipe()
					if err != nil {
						return nil, err
					}
				}
				_, err := p.expect(TokPunct, "]")
				if err != nil {
					return nil, err
				}
				opt := p.match(TokOp, "?")
				node = &SliceExpr{Target: node, Start: nil, End: endAST, Opt: opt}
			} else {
				idxExpr, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				if p.peek().Type == TokOp && p.peek().Str == ":" {
					p.next()
					var endAST ASTNode
					if !(p.peek().Type == TokPunct && p.peek().Str == "]") {
						endAST, err = p.parsePipe()
						if err != nil {
							return nil, err
						}
					}
					_, err := p.expect(TokPunct, "]")
					if err != nil {
						return nil, err
					}
					opt := p.match(TokOp, "?")
					node = &SliceExpr{Target: node, Start: idxExpr, End: endAST, Opt: opt}
				} else {
					_, err := p.expect(TokPunct, "]")
					if err != nil {
						return nil, err
					}
					opt := p.match(TokOp, "?")
					node = &IndexExpr{Target: node, Index: idxExpr, Opt: opt}
				}
			}
		} else if tok.Type == TokOp && tok.Str == "?" {
			p.next()
			if iter, ok := node.(*IterExpr); ok {
				iter.Opt = true
			} else if field, ok := node.(*FieldExpr); ok {
				field.Opt = true
			} else if idx, ok := node.(*IndexExpr); ok {
				idx.Opt = true
			} else if sl, ok := node.(*SliceExpr); ok {
				sl.Opt = true
			}
		} else {
			break
		}
	}
	return node, nil
}

func (p *Parser) parsePrimary() (ASTNode, error) {
	tok := p.peek()

	if tok.Type == TokOp && tok.Str == "." {
		p.next()
		nextTok := p.peek()
		if nextTok.Type == TokIdent {
			p.next()
			opt := p.match(TokOp, "?")
			return &FieldExpr{Target: &IdentityExpr{}, Key: &StrExpr{Parts: []StrPartAST{{Str: nextTok.Str}}}, Opt: opt}, nil
		}
		if nextTok.Type == TokString {
			p.next()
			opt := p.match(TokOp, "?")
			sExpr, err := p.parseStrExpr(nextTok)
			if err != nil {
				return nil, err
			}
			return &FieldExpr{Target: &IdentityExpr{}, Key: sExpr, Opt: opt}, nil
		}
		return &IdentityExpr{}, nil
	}

	if tok.Type == TokKeyword {
		p.next()
		switch tok.Str {
		case "null":
			return &NullExpr{}, nil
		case "true":
			return &BoolExpr{Val: true}, nil
		case "false":
			return &BoolExpr{Val: false}, nil
		case "empty":
			return &EmptyExpr{}, nil
		}
	}

	if tok.Type == TokNumber {
		p.next()
		return &NumExpr{Val: tok.Num}, nil
	}

	if tok.Type == TokString {
		p.next()
		return p.parseStrExpr(tok)
	}

	if tok.Type == TokVar {
		p.next()
		return &VarRefExpr{Name: tok.Str}, nil
	}

	if tok.Type == TokIdent {
		p.next()
		name := tok.Str
		var args []ASTNode
		if p.peek().Type == TokPunct && p.peek().Str == "(" {
			p.next()
			for {
				if p.peek().Type == TokPunct && p.peek().Str == ")" {
					break
				}
				arg, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				args = append(args, arg)
				if p.peek().Type == TokOp && p.peek().Str == ";" {
					p.next()
				} else {
					break
				}
			}
			_, err := p.expect(TokPunct, ")")
			if err != nil {
				return nil, err
			}
		}
		return &FuncCallExpr{Name: name, Args: args}, nil
	}

	if tok.Type == TokPunct && tok.Str == "(" {
		p.next()
		expr, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		_, err = p.expect(TokPunct, ")")
		if err != nil {
			return nil, err
		}
		return expr, nil
	}

	if tok.Type == TokPunct && tok.Str == "[" {
		p.next()
		if p.peek().Type == TokPunct && p.peek().Str == "]" {
			p.next()
			return &ArrayExpr{Expr: &EmptyExpr{}}, nil
		}
		expr, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		_, err = p.expect(TokPunct, "]")
		if err != nil {
			return nil, err
		}
		return &ArrayExpr{Expr: expr}, nil
	}

	if tok.Type == TokPunct && tok.Str == "{" {
		p.next()
		var fields []ObjectFieldAST
		for {
			if p.peek().Type == TokPunct && p.peek().Str == "}" {
				break
			}
			var keyAST ASTNode
			var valAST ASTNode
			var opt bool

			if p.peek().Type == TokPunct && p.peek().Str == "(" {
				p.next()
				kExpr, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				_, err = p.expect(TokPunct, ")")
				if err != nil {
					return nil, err
				}
				keyAST = kExpr
				_, err = p.expect(TokOp, ":")
				if err != nil {
					return nil, err
				}
				valAST, err = p.parseVarBind()
				if err != nil {
					return nil, err
				}
			} else if p.peek().Type == TokIdent || p.peek().Type == TokKeyword {
				kTok := p.next()
				keyAST = &StrExpr{Parts: []StrPartAST{{Str: kTok.Str}}}
				if p.peek().Type == TokOp && p.peek().Str == ":" {
					p.next()
					var err error
					valAST, err = p.parseVarBind()
					if err != nil {
						return nil, err
					}
				} else {
					valAST = &FieldExpr{Target: &IdentityExpr{}, Key: keyAST}
				}
			} else if p.peek().Type == TokString {
				sTok := p.next()
				sExpr, err := p.parseStrExpr(sTok)
				if err != nil {
					return nil, err
				}
				keyAST = sExpr
				_, err = p.expect(TokOp, ":")
				if err != nil {
					return nil, err
				}
				valAST, err = p.parseVarBind()
				if err != nil {
					return nil, err
				}
			} else {
				return nil, fmt.Errorf("unexpected token in object %q", p.peek().Str)
			}

			opt = p.match(TokOp, "?")
			fields = append(fields, ObjectFieldAST{KeyAST: keyAST, ValAST: valAST, Opt: opt})

			if p.peek().Type == TokOp && p.peek().Str == "," {
				p.next()
			} else {
				break
			}
		}
		_, err := p.expect(TokPunct, "}")
		if err != nil {
			return nil, err
		}
		return &ObjectExpr{Fields: fields}, nil
	}

	return nil, fmt.Errorf("syntax error, unexpected %s %q at line %d, column %d", formatTokenType(tok.Type), tok.Str, tok.Line, tok.Col)
}

func (p *Parser) parseStrExpr(tok Token) (ASTNode, error) {
	var parts []StrPartAST
	for _, pt := range tok.Parts {
		if pt.IsExpr {
			subParser := NewParser(pt.Expr)
			subAST, err := subParser.Parse()
			if err != nil {
				return nil, err
			}
			parts = append(parts, StrPartAST{IsExpr: true, Expr: subAST})
		} else {
			parts = append(parts, StrPartAST{Str: pt.Str})
		}
	}
	return &StrExpr{Parts: parts}, nil
}
