func (p *Parser) parseAssign() (ASTNode, error) {
	left, err := p.parseAlternative()
	if err != nil {
		return nil, err
	}
	tok := p.peek()
	if tok.Type == TokOp {
		switch tok.Str {
		case "=":
			p.next()
			right, err := p.parseAssign()
			if err != nil {
				return nil, err
			}
			return &AssignExpr{Path: left, Val: right}, nil
		case "|=":
			p.next()
			right, err := p.parseAssign()
			if err != nil {
				return nil, err
			}
			return &UpdateExpr{Path: left, Val: right}, nil
		case "+=", "-=", "*=", "/=", "%=", "//=":
			p.next()
			right, err := p.parseAssign()
			if err != nil {
				return nil, err
			}
