	if err != nil {
		return nil, err
	}
	init, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	_, err = p.expect(TokOp, ";")
	if err != nil {
		return nil, err
	}
	update, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	var extract ASTNode
	if p.peek().Type == TokOp && p.peek().Str == ";" {
		p.next()
		extract, err = p.parsePipe()
		if err != nil {
			return nil, err
		}
	}
	_, err = p.expect(TokPunct, ")")
	if err != nil {
