{"command":"cat <<'EOF' > eval.go
package main

import (
	"encoding/json"
	"fmt"
)

type FunctionClosure struct {
	Params []string
	Body   ASTNode
	Scope  *Context
}

type Context struct {
	Vars  map[string]any
	Funcs map[string]map[int]FunctionClosure
	Outer *Context
}

func NewContext(outer *Context) *Context {
	return &Context{
		Vars:  make(map[string]any),
		Funcs: make(map[string]map[int]FunctionClosure),
		Outer: outer,
	}
}

func (c *Context) GetVar(name string) (any, bool) {
	if val, ok := c.Vars[name]; ok {
		return val, true
	}
	if c.Outer != nil {
		return c.Outer.GetVar(name)
	}
	return nil, false
}

func (c *Context) SetVar(name string, val any) {
	c.Vars[name] = val
}

func (c *Context) GetFunc(name string, arity int) (FunctionClosure, bool) {
	if m, ok := c.Funcs[name]; ok {
		if fc, ok := m[arity]; ok {
			return fc, true
		}
	}
	if c.Outer != nil {
		return c.Outer.GetFunc(name, arity)
	}
	return FunctionClosure{}, false
}

func (c *Context) SetFunc(name string, arity int, fc FunctionClosure) {
	if _, ok := c.Funcs[name]; !ok {
		c.Funcs[name] = make(map[int]FunctionClosure)
	}
	c.Funcs[name][arity] = fc
}

const StdLibJQ = `
def map(f): [.[] | f];
def map_values(f): .[] |= f;
def select(f): if f then . else empty end;
def with_entries(f): to_entries | map(f) | from_entries;
def recurse(f): ., (f? | select(. != null) | recurse(f));
def recurse: recurse(.[]?);
def scalars: select(type != "array" and type != "object");
def paths: path(recurse) | select(length > 0);
def paths(f): path(recurse) | select(length > 0 and (getpath(.) | f));
def indices(s): [path(recurse) | select(getpath(.) == s)];
def index(s): indices(s)[0]? // null;
def rindex(s): indices(s)[-1]? // null;
def del(f): delpaths([path(f)]);
`

func InitBaseContext() (*Context, error) {
	ctx := NewContext(nil)
	ast, err := ParseFilter(StdLibJQ)
	if err != nil {
		return nil, err
	}
	Eval(ast, ctx, nil, func(v any) error { return nil })
	return ctx, nil
}

func Eval(node ASTNode, ctx *Context, input any, emit func(any) error) error {
	if node == nil {
		return emit(input)
	}

	switch n := node.(type) {
	case *IdentityExpr:
		return emit(input)

	case *EmptyExpr:
		return nil

	case *NullExpr:
		return emit(nil)

	case *BoolExpr:
		return emit(n.Val)

	case *NumExpr:
		return emit(n.Val)

	case *StrExpr:
		return evalStrExpr(n, ctx, input, emit)

	case *FormatExpr:
		targetInput := input
		if n.Target != nil {
			return Eval(n.Target, ctx, input, func(v any) error {
				return applyFormat(n.Fmt, v, emit)
			})
		}
		return applyFormat(n.Fmt, targetInput, emit)

	case *VarRefExpr:
		if val, ok := ctx.GetVar(n.Name); ok {
			return emit(val)
		}
		return fmt.Errorf("variable %s is not defined", n.Name)

	case *VarBindExpr:
		return Eval(n.Expr, ctx, input, func(v any) error {
			subCtx := NewContext(ctx)
			bindPattern(n.Pattern, v, subCtx)
			return Eval(n.Body, subCtx, input, emit)
		})

	case *PipeExpr:
		return Eval(n.Left, ctx, input, func(mid any) error {
			return Eval(n.Right, ctx, mid, emit)
		})

	case *CommaExpr:
		if err := Eval(n.Left, ctx, input, emit); err != nil {
			return err
		}
		return Eval(n.Right, ctx, input, emit)

	case *BinaryExpr:
		return evalBinary(n, ctx, input, emit)

	case *UnaryExpr:
		return evalUnary(n, ctx, input, emit)

	case *IfExpr:
		return evalIf(n, ctx, input, emit)

	case *TryExpr:
		err := Eval(n.Body, ctx, input, emit)
		if err != nil {
			if n.Catch != nil {
				return Eval(n.Catch, ctx, err.Error(), emit)
			}
			return nil
		}
		return nil

	case *FieldExpr:
		return evalField(n, ctx, input, emit)

	case *IndexExpr:
		return evalIndex(n, ctx, input, emit)

	case *SliceExpr:
		return evalSlice(n, ctx, input, emit)

	case *IterExpr:
		return evalIter(n, ctx, input, emit)

	case *ArrayExpr:
		var arr []any
		err := Eval(n.Expr, ctx, input, func(v any) error {
			arr = append(arr, v)
			return nil
		})
		if err != nil {
			return err
		}
		if arr == nil {
			arr = make([]any, 0)
		}
		return emit(arr)

	case *ObjectExpr:
		return evalObject(n, ctx, input, emit)

	case *AssignExpr:
		return evalAssign(n, ctx, input, emit)

	case *UpdateExpr:
		return evalUpdate(n, ctx, input, emit)

	case *OpAssignExpr:
		return evalOpAssign(n, ctx, input, emit)

	case *FuncDefExpr:
		arity := len(n.Params)
		fc := FunctionClosure{Params: n.Params, Body: n.Body, Scope: ctx}
		ctx.SetFunc(n.Name, arity, fc)
		if n.Next != nil {
			return Eval(n.Next, ctx, input, emit)
		}
		return nil

	case *FuncCallExpr:
		return evalFuncCall(n, ctx, input, emit)

	case *ReduceExpr:
		return evalReduce(n, ctx, input, emit)

	case *ForeachExpr:
		return evalForeach(n, ctx, input, emit)
	}

	return fmt.Errorf("unhandled AST node %T", node)
}

func bindPattern(pat PatternAST, val any, ctx *Context) {
	if pat.VarName != "" {
		ctx.SetVar(pat.VarName, val)
		return
	}
	if len(pat.Array) > 0 {
		arr, ok := val.([]any)
		for i, subPat := range pat.Array {
			var elem any
			if ok && i < len(arr) {
				elem = arr[i]
			}
			bindPattern(subPat, elem, ctx)
		}
		return
	}
	if len(pat.ObjFields) > 0 {
		for _, f := range pat.ObjFields {
			valKey, _ := getObjectKey(val, f.Key)
			bindPattern(f.Pattern, valKey, ctx)
		}
		return
	}
}

func evalStrExpr(n *StrExpr, ctx *Context, input any, emit func(any) error) error {
	var rec func(idx int, currentStr string) error
	rec = func(idx int, currentStr string) error {
		if idx == len(n.Parts) {
			return emit(currentStr)
		}
		pt := n.Parts[idx]
		if !pt.IsExpr {
			return rec(idx+1, currentStr+pt.Str)
		}
		return Eval(pt.Expr, ctx, input, func(v any) error {
			partStr := ""
			if s, isStr := v.(string); isStr {
				partStr = s
			} else {
				partStr = FormatCompact(v)
			}
			return rec(idx+1, currentStr+partStr)
		})
	}
	return rec(0, "")
}

func applyFormat(fmtName string, v any, emit func(any) error) error {
	var res string
	var err error
	switch fmtName {
	case "@json":
		res = FormatCompact(v)
	case "@text":
		if s, isStr := v.(string); isStr {
			res = s
		} else {
			res = FormatCompact(v)
		}
	case "@csv":
		res, err = FormatCSV(v)
	case "@tsv":
		res, err = FormatTSV(v)
	case "@sh":
		res, err = FormatSH(v)
	case "@html":
		res, err = FormatHTML(v)
	case "@uri":
		res, err = FormatURI(v)
	case "@base64":
		res, err = FormatBase64(v)
	case "@base64d":
		res, err = FormatBase64Decode(v)
	default:
		return fmt.Errorf("unknown formatter %s", fmtName)
	}
	if err != nil {
		return err
	}
	return emit(res)
}

func evalBinary(n *BinaryExpr, ctx *Context, input any, emit func(any) error) error {
	if n.Op == "//" {
		hasTruthy := false
		err := Eval(n.Left, ctx, input, func(v any) error {
			if IsTruthy(v) {
				hasTruthy = true
				return emit(v)
			}
			return nil
		})
		if err != nil {
			return err
		}
		if !hasTruthy {
			return Eval(n.Right, ctx, input, emit)
		}
		return nil
	}

	return Eval(n.Left, ctx, input, func(v1 any) error {
		return Eval(n.Right, ctx, input, func(v2 any) error {
			switch n.Op {
			case "+":
				res, err := Add(v1, v2)
				if err != nil {
					return err
				}
				return emit(res)
			case "-":
				res, err := Sub(v1, v2)
				if err != nil {
					return err
				}
				return emit(res)
			case "*":
				res, err := Mul(v1, v2)
				if err != nil {
					return err
				}
				return emit(res)
			case "/":
				res, err := Div(v1, v2)
				if err != nil {
					return err
				}
				return emit(res)
			case "%":
				res, err := Mod(v1, v2)
				if err != nil {
					return err
				}
				return emit(res)
			case "==":
				return emit(Compare(v1, v2) == 0)
			case "!=":
				return emit(Compare(v1, v2) != 0)
			case "<":
				return emit(Compare(v1, v2) < 0)
			case "<=":
				return emit(Compare(v1, v2) <= 0)
			case ">":
				return emit(Compare(v1, v2) > 0)
			case ">=":
				return emit(Compare(v1, v2) >= 0)
			case "and":
				return emit(IsTruthy(v1) && IsTruthy(v2))
			case "or":
				return emit(IsTruthy(v1) || IsTruthy(v2))
			}
			return fmt.Errorf("unknown binary operator %s", n.Op)
		})
	})
}

func evalUnary(n *UnaryExpr, ctx *Context, input any, emit func(any) error) error {
	return Eval(n.Right, ctx, input, func(v any) error {
		switch n.Op {
		case "-":
			return emit(-ToFloat(v))
		case "+":
			return emit(ToFloat(v))
		case "not":
			return emit(!IsTruthy(v))
		}
		return fmt.Errorf("unknown unary operator %s", n.Op)
	})
}

func evalIf(n *IfExpr, ctx *Context, input any, emit func(any) error) error {
	return Eval(n.Cond, ctx, input, func(c any) error {
		if IsTruthy(c) {
			return Eval(n.Then, ctx, input, emit)
		}
		for _, elif := range n.Elifs {
			var elifCondVal any
			Eval(elif.Cond, ctx, input, func(ec any) error {
				elifCondVal = ec
				return nil
			})
			if IsTruthy(elifCondVal) {
				return Eval(elif.Then, ctx, input, emit)
			}
		}
		if n.Else != nil {
			return Eval(n.Else, ctx, input, emit)
		}
		return nil
	})
}

func evalField(n *FieldExpr, ctx *Context, input any, emit func(any) error) error {
	return Eval(n.Key, ctx, input, func(kVal any) error {
		kStr, isStr := kVal.(string)
		if !isStr {
			kStr = FormatCompact(kVal)
		}
		return Eval(n.Target, ctx, input, func(tVal any) error {
			if obj, ok := tVal.(*JqObject); ok {
				val, exists := obj.Map[kStr]
				if exists {
					return emit(val)
				}
				return emit(nil)
			}
			if m, ok := tVal.(map[string]any); ok {
				val, exists := m[kStr]
				if exists {
					return emit(val)
				}
				return emit(nil)
			}
			if n.Opt || tVal == nil {
				return nil
			}
			return fmt.Errorf("cannot index %s with string %q", TypeName(tVal), kStr)
		})
	})
}

func evalIndex(n *IndexExpr, ctx *Context, input any, emit func(any) error) error {
	return Eval(n.Index, ctx, input, func(iVal any) error {
		idx := int(ToFloat(iVal))
		return Eval(n.Target, ctx, input, func(tVal any) error {
			if arr, ok := tVal.([]any); ok {
				if idx < 0 {
					idx = len(arr) + idx
				}
				if idx >= 0 && idx < len(arr) {
					return emit(arr[idx])
				}
				return emit(nil)
			}
			if n.Opt || tVal == nil {
				return nil
			}
			return fmt.Errorf("cannot index %s with number %d", TypeName(tVal), idx)
		})
	})
}

func evalSlice(n *SliceExpr, ctx *Context, input any, emit func(any) error) error {
	return Eval(n.Target, ctx, input, func(tVal any) error {
		arr, ok := tVal.([]any)
		if !ok {
			if n.Opt || tVal == nil {
				return nil
			}
			return fmt.Errorf("cannot slice %s", TypeName(tVal))
		}
		startIdx := 0
		endIdx := len(arr)

		if n.Start != nil {
			Eval(n.Start, ctx, input, func(sv any) error {
				startIdx = int(ToFloat(sv))
				return nil
			})
		}
		if n.End != nil {
			Eval(n.End, ctx, input, func(ev any) error {
				endIdx = int(ToFloat(ev))
				return nil
			})
		}

		if startIdx < 0 {
			startIdx = len(arr) + startIdx
		}
		if endIdx < 0 {
			endIdx = len(arr) + endIdx
		}
		if startIdx < 0 {
			startIdx = 0
		}
		if endIdx > len(arr) {
			endIdx = len(arr)
		}
		if startIdx >= endIdx || startIdx >= len(arr) {
			return emit(make([]any, 0))
		}
		res := make([]any, endIdx-startIdx)
		copy(res, arr[startIdx:endIdx])
		return emit(res)
	})
}

func evalIter(n *IterExpr, ctx *Context, input any, emit func(any) error) error {
	return Eval(n.Target, ctx, input, func(tVal any) error {
		if arr, ok := tVal.([]any); ok {
			for _, elem := range arr {
				if err := emit(elem); err != nil {
					return err
				}
			}
			return nil
		}
		if obj, ok := tVal.(*JqObject); ok {
			for _, k := range obj.Keys {
				if err := emit(obj.Map[k]); err != nil {
					return err
				}
			}
			return nil
		}
		if n.Opt || tVal == nil {
			return nil
		}
		return fmt.Errorf("cannot iterate over %s", TypeName(tVal))
	})
}

func evalObject(n *ObjectExpr, ctx *Context, input any, emit func(any) error) error {
	var rec func(idx int, currentObj *JqObject) error
	rec = func(idx int, currentObj *JqObject) error {
		if idx == len(n.Fields) {
			return emit(currentObj.Clone())
		}
		field := n.Fields[idx]
		return Eval(field.KeyAST, ctx, input, func(kVal any) error {
			kStr, isStr := kVal.(string)
			if !isStr {
				kStr = FormatCompact(kVal)
			}
			return Eval(field.ValAST, ctx, input, func(vVal any) error {
				newObj := currentObj.Clone()
				newObj.Set(kStr, vVal)
				return rec(idx+1, newObj)
			})
		})
	}
	return rec(0, NewJqObject())
}

func evalAssign(n *AssignExpr, ctx *Context, input any, emit func(any) error) error {
	paths, err := EvalPath(n.Path, ctx, input)
	if err != nil {
		return err
	}
	return Eval(n.Val, ctx, input, func(vVal any) error {
		res := DeepCopy(input)
		for _, p := range paths {
			res = SetPath(res, p, DeepCopy(vVal))
		}
		return emit(res)
	})
}

func evalUpdate(n *UpdateExpr, ctx *Context, input any, emit func(any) error) error {
	paths, err := EvalPath(n.Path, ctx, input)
	if err != nil {
		return err
	}
	res := DeepCopy(input)
	for _, p := range paths {
		currVal := GetPath(res, p)
		Eval(n.Val, ctx, currVal, func(newVal any) error {
			res = SetPath(res, p, newVal)
			return nil
		})
	}
	return emit(res)
}

func evalOpAssign(n *OpAssignExpr, ctx *Context, input any, emit func(any) error) error {
	op := n.Op[:len(n.Op)-1]
	paths, err := EvalPath(n.Path, ctx, input)
	if err != nil {
		return err
	}
	res := DeepCopy(input)
	for _, p := range paths {
		currVal := GetPath(res, p)
		Eval(n.Val, ctx, currVal, func(rhsVal any) error {
			var newVal any
			var err error
			switch op {
			case "+":
				newVal, err = Add(currVal, rhsVal)
			case "-":
				newVal, err = Sub(currVal, rhsVal)
			case "*":
				newVal, err = Mul(currVal, rhsVal)
			case "/":
				newVal, err = Div(currVal, rhsVal)
			case "%":
				newVal, err = Mod(currVal, rhsVal)
			case "//":
				if IsTruthy(currVal) {
					newVal = currVal
				} else {
					newVal = rhsVal
				}
			}
			if err != nil {
				return err
			}
			res = SetPath(res, p, newVal)
			return nil
		})
	}
	return emit(res)
}

func evalReduce(n *ReduceExpr, ctx *Context, input any, emit func(any) error) error {
	var state any
	Eval(n.Init, ctx, input, func(initVal any) error {
		state = initVal
		return nil
	})

	err := Eval(n.Expr, ctx, input, func(item any) error {
		subCtx := NewContext(ctx)
		bindPattern(n.Pattern, item, subCtx)
		return Eval(n.Update, subCtx, state, func(nextState any) error {
			state = nextState
			return nil
		})
	})
	if err != nil {
		return err
	}
	return emit(state)
}

func evalForeach(n *ForeachExpr, ctx *Context, input any, emit func(any) error) error {
	var state any
	Eval(n.Init, ctx, input, func(initVal any) error {
		state = initVal
		return nil
	})

	return Eval(n.Expr, ctx, input, func(item any) error {
		subCtx := NewContext(ctx)
		bindPattern(n.Pattern, item, subCtx)
		return Eval(n.Update, subCtx, state, func(nextState any) error {
			state = nextState
			if n.Extract != nil {
				return Eval(n.Extract, subCtx, state, emit)
			}
			return emit(state)
		})
	})
}

func evalFuncCall(n *FuncCallExpr, ctx *Context, input any, emit func(any) error) error {
	arity := len(n.Args)

	if n.Name == "path" && arity == 1 {
		paths, err := EvalPath(n.Args[0], ctx, input)
		if err != nil {
			return err
		}
		for _, p := range paths {
			if err := emit(p); err != nil {
				return err
			}
		}
		return nil
	}

	if n.Name == "getpath" && arity == 1 {
		return Eval(n.Args[0], ctx, input, func(pVal any) error {
			pArr, ok := pVal.([]any)
			if !ok {
				return fmt.Errorf("getpath requires array path")
			}
			return emit(GetPath(input, pArr))
		})
	}

	if n.Name == "setpath" && arity == 2 {
		return Eval(n.Args[0], ctx, input, func(pVal any) error {
			pArr, ok := pVal.([]any)
			if !ok {
				return fmt.Errorf("setpath requires array path")
			}
			return Eval(n.Args[1], ctx, input, func(vVal any) error {
				return emit(SetPath(DeepCopy(input), pArr, vVal))
			})
		})
	}

	if n.Name == "delpaths" && arity == 1 {
		return Eval(n.Args[0], ctx, input, func(pVal any) error {
			pArrArr, ok := pVal.([]any)
			if !ok {
				return fmt.Errorf("delpaths requires array of paths")
			}
			res := DeepCopy(input)
			for _, pItem := range pArrArr {
				if pPath, ok := pItem.([]any); ok {
					res = DelPath(res, pPath)
				}
			}
			return emit(res)
		})
	}

	if fc, ok := ctx.GetFunc(n.Name, arity); ok {
		subCtx := NewContext(fc.Scope)
		for i, pName := range fc.Params {
			argAST := n.Args[i]
			subCtx.SetFunc(pName, 0, FunctionClosure{
				Params: nil,
				Body:   argAST,
				Scope:  ctx,
			})
		}
		return Eval(fc.Body, subCtx, input, emit)
	}

	if bArities, ok := Builtins[n.Name]; ok {
		if bFunc, ok := bArities[arity]; ok {
			return bFunc(ctx, input, n.Args, emit)
		}
	}

	return fmt.Errorf("%s/%d is not defined", n.Name, arity)
}

func EvalPath(node ASTNode, ctx *Context, input any) ([][]any, error) {
	var paths [][]any

	switch n := node.(type) {
	case *IdentityExpr:
		paths = append(paths, []any{})

	case *FuncCallExpr:
		if fc, ok := ctx.GetFunc(n.Name, len(n.Args)); ok {
			subCtx := NewContext(fc.Scope)
			for i, pName := range fc.Params {
				argAST := n.Args[i]
				subCtx.SetFunc(pName, 0, FunctionClosure{
					Params: nil,
					Body:   argAST,
					Scope:  ctx,
				})
			}
			return EvalPath(fc.Body, subCtx, input)
		}

	case *FieldExpr:
		var targetPaths [][]any
		if n.Target != nil {
			var err error
			targetPaths, err = EvalPath(n.Target, ctx, input)
			if err != nil {
				return nil, err
			}
		} else {
			targetPaths = [][]any{{}}
		}
		Eval(n.Key, ctx, input, func(kVal any) error {
			kStr, isStr := kVal.(string)
			if !isStr {
				kStr = FormatCompact(kVal)
			}
			for _, tp := range targetPaths {
				p := make([]any, len(tp)+1)
				copy(p, tp)
				p[len(tp)] = kStr
				paths = append(paths, p)
			}
			return nil
		})

	case *IndexExpr:
		var targetPaths [][]any
		if n.Target != nil {
			var err error
			targetPaths, err = EvalPath(n.Target, ctx, input)
			if err != nil {
				return nil, err
			}
		} else {
			targetPaths = [][]any{{}}
		}
		Eval(n.Index, ctx, input, func(iVal any) error {
			idx := int(ToFloat(iVal))
			for _, tp := range targetPaths {
				p := make([]any, len(tp)+1)
				copy(p, tp)
				p[len(tp)] = idx
				paths = append(paths, p)
			}
			return nil
		})

	case *IterExpr:
		var targetPaths [][]any
		if n.Target != nil {
			var err error
			targetPaths, err = EvalPath(n.Target, ctx, input)
			if err != nil {
				return nil, err
			}
		} else {
			targetPaths = [][]any{{}}
		}
		for _, tp := range targetPaths {
			currVal := GetPath(input, tp)
			if arr, ok := currVal.([]any); ok {
				for i := range arr {
					p := make([]any, len(tp)+1)
					copy(p, tp)
					p[len(tp)] = i
					paths = append(paths, p)
				}
			} else if obj, ok := currVal.(*JqObject); ok {
				for _, k := range obj.Keys {
					p := make([]any, len(tp)+1)
					copy(p, tp)
					p[len(tp)] = k
					paths = append(paths, p)
				}
			}
		}

	case *CommaExpr:
		p1, err := EvalPath(n.Left, ctx, input)
		if err != nil {
			return nil, err
		}
		p2, err := EvalPath(n.Right, ctx, input)
		if err != nil {
			return nil, err
		}
		paths = append(paths, p1...)
		paths = append(paths, p2...)

	case *PipeExpr:
		p1, err := EvalPath(n.Left, ctx, input)
		if err != nil {
			return nil, err
		}
		for _, path1 := range p1 {
			subInput := GetPath(input, path1)
			p2, err := EvalPath(n.Right, ctx, subInput)
			if err != nil {
				return nil, err
			}
			for _, path2 := range p2 {
				fullPath := make([]any, len(path1)+len(path2))
				copy(fullPath, path1)
				copy(fullPath[len(path1):], path2)
				paths = append(paths, fullPath)
			}
		}
	}

	return paths, nil
}

func GetPath(input any, path []any) any {
	curr := input
	for _, p := range path {
		if curr == nil {
			return nil
		}
		if s, isStr := p.(string); isStr {
			val, _ := getObjectKey(curr, s)
			curr = val
		} else if idx, isInt := p.(int); isInt {
			if arr, ok := curr.([]any); ok {
				if idx < 0 {
					idx = len(arr) + idx
				}
				if idx >= 0 && idx < len(arr) {
					curr = arr[idx]
				} else {
					return nil
				}
			} else {
				return nil
			}
		} else if f, isFloat := p.(float64); isFloat {
			idx := int(f)
			if arr, ok := curr.([]any); ok {
				if idx < 0 {
					idx = len(arr) + idx
				}
				if idx >= 0 && idx < len(arr) {
					curr = arr[idx]
				} else {
					return nil
				}
			} else {
				return nil
			}
		}
	}
	return curr
}

func SetPath(input any, path []any, val any) any {
	if len(path) == 0 {
		return val
	}
	first := path[0]
	rest := path[1:]

	if s, isStr := first.(string); isStr {
		obj, ok := input.(*JqObject)
		if !ok || obj == nil {
			obj = NewJqObject()
		} else {
			obj = obj.Clone()
		}
		childVal := obj.Map[s]
		obj.Set(s, SetPath(childVal, rest, val))
		return obj
	}

	idx := 0
	if i, isInt := first.(int); isInt {
		idx = i
	} else if f, isFloat := first.(float64); isFloat {
		idx = int(f)
	}

	arr, ok := input.([]any)
	if !ok || arr == nil {
		arr = make([]any, 0)
	} else {
		newArr := make([]any, len(arr))
		copy(newArr, arr)
		arr = newArr
	}

	if idx < 0 {
		idx = len(arr) + idx
	}
	if idx < 0 {
		idx = 0
	}

	for len(arr) <= idx {
		arr = append(arr, nil)
	}

	childVal := arr[idx]
	arr[idx] = SetPath(childVal, rest, val)
	return arr
}

func DelPath(input any, path []any) any {
	if len(path) == 0 {
		return nil
	}
	if len(path) == 1 {
		p := path[0]
		if s, isStr := p.(string); isStr {
			if obj, ok := input.(*JqObject); ok {
				newObj := obj.Clone()
				newObj.Delete(s)
				return newObj
			}
		} else {
			idx := 0
			if i, isInt := p.(int); isInt {
				idx = i
			} else if f, isFloat := p.(float64); isFloat {
				idx = int(f)
			}
			if arr, ok := input.([]any); ok {
				if idx < 0 {
					idx = len(arr) + idx
				}
				if idx >= 0 && idx < len(arr) {
					newArr := make([]any, 0, len(arr)-1)
					newArr = append(newArr, arr[:idx]...)
					newArr = append(newArr, arr[idx+1:]...)
					return newArr
				}
			}
		}
		return input
	}

	first := path[0]
	rest := path[1:]

	if s, isStr := first.(string); isStr {
		if obj, ok := input.(*JqObject); ok {
			newObj := obj.Clone()
			if childVal, exists := newObj.Map[s]; exists {
				newObj.Set(s, DelPath(childVal, rest))
			}
			return newObj
		}
	} else {
		idx := 0
		if i, isInt := first.(int); isInt {
			idx = i
		} else if f, isFloat := first.(float64); isFloat {
			idx = int(f)
		}
		if arr, ok := input.([]any); ok {
			if idx < 0 {
				idx = len(arr) + idx
			}
			if idx >= 0 && idx < len(arr) {
				newArr := make([]any, len(arr))
				copy(newArr, arr)
				newArr[idx] = DelPath(arr[idx], rest)
				return newArr
			}
		}
	}
	return input
}

func decodeJSON(dec *json.Decoder) (any, error) {
	t, err := dec.Token()
	if err != nil {
		return nil, err
	}
	return parseToken(dec, t)
}

func parseToken(dec *json.Decoder, t json.Token) (any, error) {
	switch v := t.(type) {
	case nil:
		return nil, nil
	case bool:
		return v, nil
	case json.Number:
		if f, err := v.Float64(); err == nil {
			return f, nil
		}
		return v, nil
	case float64:
		return v, nil
	case string:
		return v, nil
	case json.Delim:
		if v == '[' {
			var arr []any
			for dec.More() {
				elem, err := decodeJSON(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, elem)
			}
			dec.Token() // consume ']'
			return arr, nil
		} else if v == '{' {
			obj := NewJqObject()
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				keyStr, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				val, err := decodeJSON(dec)
				if err != nil {
					return nil, err
				}
				obj.Set(keyStr, val)
			}
			dec.Token() // consume '}'
			return obj, nil
		}
	}
	return nil, fmt.Errorf("unexpected token %v", t)
}
