		}
		return checkFunctions(n.Val, ctx)
	case *UpdateExpr:
		if err := checkFunctions(n.Path, ctx); err != nil {
			return err
		}
		return checkFunctions(n.Val, ctx)
	case *OpAssignExpr:
		if err := checkFunctions(n.Path, ctx); err != nil {
			return err
		}
		return checkFunctions(n.Val, ctx)
	case *FuncDefExpr:
		subCtx := NewContext(ctx)
		subCtx.SetFunc(n.Name, len(n.Params), FunctionClosure{Params: n.Params, Body: n.Body, Scope: subCtx})
