			case "--ascii-output":
				opts.ASCII = true
			case "--sort-keys":
				opts.SortKeys = true
			case "--color-output":
				opts.Color = true
			case "--monochrome-output":
				opts.Color = false
			case "--tab":
				opts.Indent = -1
			case "--exit-status":
				exitStatusFlag = true
			case "--unbuffered":
				unbuffered = true
			case "--seq":
				opts.Seq = true
			case "--indent":
				i++
				if i >= len(args) {
					fmt.Fprintf(os.Stderr, "jq: option --indent requires an argument\n")
					os.Exit(2)
				}
				n, err := strconv.Atoi(args[i])
				if err != nil || n < -1 || n > 7 {
					fmt.Fprintf(os.Stderr, "jq: --indent takes a number between -1 and 7\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n")
					os.Exit(2)
				}
				opts.Indent = n
			case "--from-file":
				i++
				if i >= len(args) {
					fmt.Fprintf(os.Stderr, "jq: option -f requires an argument\n")
					os.Exit(2)
				}
				filterFile = args[i]
			case "--library-path":
				i++
			case "--arg":
				if i+2 >= len(args) {
					fmt.Fprintf(os.Stderr, "jq: option --arg requires two arguments\n")
					os.Exit(2)
