			}
		}
	} else {
		dec := json.NewDecoder(r)
		dec.UseNumber()
		for {
			val, err := decodeJSON(dec)
			if err == io.EOF {
				break
			}
			if err != nil {
				break
			}
			*inputs = append(*inputs, val)
		}
	}
